hemma_battery.state_display:
[[[
  const list = variables.batteries || variables.entity_filter;
  const batteries = (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).filter(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    if (isNaN(parseFloat(e.state))) return false;
    return e.attributes.device_class === 'battery';
  });
  if (batteries.length === 0) return 'No Sensors';
  const anyLow = batteries.some(e => parseFloat(e.state) <= 20);
  return anyLow ? 'Needs Attention' : 'Healthy';
]]]

state.value:
[[[
  const list = variables.batteries || variables.entity_filter;
  return (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).some(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    const pct = parseFloat(e.state);
    if (isNaN(pct)) return false;
    return e.attributes.device_class === 'battery' && pct <= 20;
  });
]]]

hemma_cameras.state_display:
[[[
  const cams = Array.isArray(variables.cameras) ? variables.cameras.filter(Boolean) : [];
  if (!cams.length) return 'No Cameras';
  const dead = cams.filter(id => ['unavailable','unknown',''].includes(String(states[id]?.state ?? '').toLowerCase())).length;
  if (dead === cams.length) return cams.length === 1 ? 'Offline' : 'All Offline';
  if (dead > 0) return dead + ' Offline';
  const alert = window.hemmaCameraAlert ? window.hemmaCameraAlert(hass, states, cams, variables.alert_window_minutes) : '';
  return alert || 'No Alerts';
]]]

hemma_energy.state_display:
[[[
  const id = variables.entity_power || entity?.entity_id;
  const w = parseFloat(states[id]?.state);
  if (!Number.isFinite(w)) return 'Unavailable';
  if (w >= Number(variables.extreme_threshold ?? 3000)) return 'Extreme Usage';
  if (w >= Number(variables.heavy_threshold   ?? 1000)) return 'Heavy Usage';
  if (w >= Number(variables.normal_threshold  ?? 200))  return 'Normal';
  return 'Idle';
]]]

state.value:
[[[
  // Hysteresis: smart-row sorts off this state, so a sensor hovering at
  // the trigger would reshuffle the row on every crossing. Release lower.
  const w = parseFloat(entity?.state);
  if (!Number.isFinite(w)) { this._hemmaEnergyActive = false; return false; }
  const on  = Number(variables.high_threshold ?? 500);
  const off = Number(variables.release_threshold ?? on * 0.8);
  const now = this._hemmaEnergyActive === true ? (w >= off) : (w >= on);
  this._hemmaEnergyActive = now;
  return now;
]]]

card.--hemma-actions-pad-right:
[[[
  const on = (idx) => {
    const enabled = variables[`action_${idx}_enabled`];
    const ok = (enabled === undefined || enabled === null) ? true :
      (typeof enabled === 'boolean') ? enabled :
      (typeof enabled === 'number') ? enabled !== 0 :
      !['false','0','no','off','disabled'].includes(String(enabled).trim().toLowerCase());
    return ok && !!variables[`action_${idx}_entity`];
  };
  const count = (on(1) ? 1 : 0) + (on(2) ? 1 : 0);
  return count > 0
    ? 'calc(var(--hemma-actions-rail-w) + var(--hemma-actions-rail-inset))'
    : 'var(--hemma-actions-pad)';
]]]

