custom_fields.side_actions:
[[[
  const esc = (v) =>
    String(v ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

  const getEntityStateClass = (eid) => {
    if (!eid || !states[eid]) return 'unavailable';

    const st = String(states[eid]?.state || '').toLowerCase().replace(/_/g, ' ');

    const active = [
      'on', 'open', 'opening', 'unlocked', 'unlocking',
      'playing', 'buffering', 'home', 'connected', 'online',
      'cooling', 'heating', 'cleaning', 'running', 'active'
    ];

    const bad = ['unknown', 'unavailable', 'none', ''];

    if (bad.includes(st)) return 'unavailable';
    if (active.includes(st)) return 'active';
    return 'normal';
  };

  // Mirrors the domain accent map in hemma_entity so an active button reads the
  // same color the tile's own icon circle would use for that domain.
  const accentFor = (idx, eid) => {
    const override = variables[`action_${idx}_active_color`];
    if (override) return String(override);

    const teal = 'var(--hemma-color-teal, #00c3d0)';
    const byDomain = {
      light:         'var(--hemma-color-yellow, #FFCC00)',
      fan:           'var(--hemma-color-teal, #00C3D0)',
      humidifier:    'var(--hemma-color-teal, #00C3D0)',
      climate:       'var(--hemma-color-teal, #00C3D0)',
      vacuum:        'var(--hemma-color-teal, #00C3D0)',
      cover:         teal,
      media_player:  teal,
      lock:          teal,
      switch:        teal,
      input_boolean: teal,
      script:        teal,
      automation:    teal,
    };

    return byDomain[String(eid || '').split('.')[0]] || teal;
  };

  const renderIcon = (iconRaw, eid, cls) => {
    const raw = String(iconRaw || states[eid]?.attributes?.icon || 'mdi:help-circle').trim();

    if (raw.includes(':')) {
      return `
        <ha-icon
          class="hemma-side-action-icon hemma-side-action-ha-icon ${cls}"
          icon="${esc(raw)}">
        </ha-icon>
      `;
    }

    if (
      raw.startsWith('/') ||
      raw.startsWith('http://') ||
      raw.startsWith('https://') ||
      raw.endsWith('.svg') ||
      raw.endsWith('.png') ||
      raw.endsWith('.webp')
    ) {
      return `
        <img
          class="hemma-side-action-icon hemma-side-action-svg ${cls}"
          src="${esc(raw)}"
          alt="">
      `;
    }

    const base = String(variables.svg_path || '/local/hemma/icons').replace(/\/$/, '');
    const src = `${base}/${raw}.svg`;

    return `
      <img
        class="hemma-side-action-icon hemma-side-action-svg ${cls}"
        src="${esc(src)}"
        alt="">
    `;
  };

  const isEnabled = (idx) => {
    const enabled = variables[`action_${idx}_enabled`];
    const eid = variables[`action_${idx}_entity`];

    const ok = (enabled === undefined || enabled === null) ? true :
      (typeof enabled === 'boolean') ? enabled :
      (typeof enabled === 'number') ? enabled !== 0 :
      !['false','0','no','off','disabled'].includes(String(enabled).trim().toLowerCase());

    return ok && !!eid;
  };

  const runAction = (idx) => {
    const eid = variables[`action_${idx}_entity`];
    if (!eid) return;

    const action = variables[`action_${idx}_action`] || 'more-info';

    if (action === 'more-info') {
      this.dispatchEvent(new CustomEvent('hass-more-info', {
        bubbles: true,
        composed: true,
        detail: { entityId: eid }
      }));
      return;
    }

    if (action === 'toggle') {
      const domain = String(eid).split('.')[0];
      if (!domain) return;
      hass.callService(domain, 'toggle', { entity_id: eid });
      return;
    }

    if (action === 'call-service') {
      const full = variables[`action_${idx}_service`];
      if (!full || !String(full).includes('.')) return;

      const [domain, service] = String(full).split('.');
      const data = Object.assign({}, variables[`action_${idx}_service_data`] || {});

      if (!data.entity_id) {
        data.entity_id = eid;
      }

      hass.callService(domain, service, data);
      return;
    }

    if (action === 'navigate') {
      const path = variables[`action_${idx}_navigation_path`];
      if (!path) return;

      history.pushState(null, '', path);
      window.dispatchEvent(new Event('location-changed'));
      return;
    }
  };

  setTimeout(() => {
    try {
      const root = this.shadowRoot;
      if (!root) return;

      root.querySelectorAll('.hemma-side-action-button[data-action-index]').forEach((el) => {
        if (el._hemmaSideBound) return;
        el._hemmaSideBound = true;

        el.addEventListener('click', (ev) => {
          ev.preventDefault();
          ev.stopPropagation();
          const idx = el.getAttribute('data-action-index');
          runAction(idx);
        });

        el.addEventListener('pointerdown', (ev) => {
          ev.stopPropagation();
        });

        ['touchstart', 'touchmove', 'touchend', 'touchcancel'].forEach((type) => {
          el.addEventListener(type, (ev) => {
            ev.stopPropagation();
          }, { passive: true });
        });
      });
    } catch(e) {}
  }, 0);

  const btn = (idx) => {
    if (!isEnabled(idx)) return '';

    const eid = variables[`action_${idx}_entity`];
    const icon = variables[`action_${idx}_icon`];
    const cls = getEntityStateClass(eid);
    const label = states[eid]?.attributes?.friendly_name || eid;

    return `
      <div
        class="hemma-side-action-button hemma-side-action-${idx} ${cls}"
        data-action-index="${idx}"
        style="--hemma-side-action-accent: ${esc(accentFor(idx, eid))};"
        title="${esc(label)}">
        ${renderIcon(icon, eid, cls)}
      </div>
    `;
  };

  return `${btn(1)}${btn(2)}`;
]]]

hemma_entity_actions.extra_styles:
/* Responsive tokens */
:host {
  --hemma-actions-pad: var(--hemma-entity-inner-pad-current, var(--hemma-entity-inner-pad-desktop, 20px));
  --hemma-actions-rail-w: 56px;
  --hemma-actions-rail-inset: 22px;
  --hemma-actions-gap: 6px;
  --hemma-actions-btn-radius: 18px;
  --hemma-actions-icon-size: 23px;
  --hemma-actions-svg-size: 20px;
}

@media (max-width: 767px), (max-height: 600px) {
  :host {
    --hemma-actions-rail-w: 56px;
    --hemma-actions-rail-inset: 14px;
    --hemma-actions-gap: 5px;
    --hemma-actions-btn-radius: 15px;
    --hemma-actions-icon-size: 22px;
    --hemma-actions-svg-size: 19px;
  }
}

#side_actions {
  overflow: visible !important;
  pointer-events: auto !important;
}

/* Buttons */
.hemma-side-action-button {
  flex: 0 0 calc(50% - var(--hemma-actions-gap) / 2);
  width: 100%;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 0;
  margin: 0;

  cursor: pointer;
  pointer-events: auto;
  user-select: none;
  -webkit-tap-highlight-color: transparent;

  background: var(--hemma-entity-actions-btn-bg, rgba(255, 255, 255, 0.09));
  border-radius: var(--hemma-actions-btn-radius);
  box-shadow: none;
  overflow: hidden;

  transition: background-color 0.18s ease, transform 0.15s ease;
}

.hemma-side-action-button.active {
  background: var(--hemma-side-action-accent, var(--hemma-color-teal, #00c3d0));
}

/* Icons */
.hemma-side-action-icon {
  display: block;
  object-fit: contain;

  background: transparent !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: none;

  color: var(--primary-text-color);
  opacity: 0.86;

  transition: color 0.18s ease, opacity 0.18s ease;
}

.hemma-side-action-ha-icon {
  --mdc-icon-size: var(--hemma-actions-icon-size);
  width: var(--hemma-actions-icon-size);
  height: var(--hemma-actions-icon-size);
  min-width: var(--hemma-actions-icon-size);
  max-width: var(--hemma-actions-icon-size);
}

.hemma-side-action-svg {
  width: var(--hemma-actions-svg-size);
  height: var(--hemma-actions-svg-size);
  min-width: var(--hemma-actions-svg-size);
  max-width: var(--hemma-actions-svg-size);
  object-fit: contain;
}

/* Active button */
.hemma-side-action-icon.active {
  color: #fff;
  opacity: 1;
}

.hemma-side-action-svg.active {
  filter: brightness(0) invert(1);
}

.hemma-side-action-icon.normal {
  opacity: 0.82;
}

.hemma-side-action-icon.unavailable {
  opacity: 0.35;
  color: var(--disabled-text-color);
  filter: grayscale(1);
}

.hemma-side-action-button ha-icon,
.hemma-side-action-button img,
.hemma-side-action-button *,
#side_actions ha-icon,
#side_actions img {
  background: transparent !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* Interaction */
@media (hover: hover) and (pointer: fine) {
  .hemma-side-action-button:hover {
    background: var(--hemma-entity-actions-btn-bg-hover, rgba(255, 255, 255, 0.16));
  }

  .hemma-side-action-button.active:hover {
    background: var(--hemma-side-action-accent, var(--hemma-color-teal, #00c3d0));
    filter: brightness(1.12);
  }
}

.hemma-side-action-button:active {
  transform: scale(0.96);
}

@media (hover: none) and (pointer: coarse) {
  .hemma-side-action-button:active {
    background: var(--hemma-entity-actions-btn-bg-hover, rgba(255, 255, 255, 0.16));
  }

  .hemma-side-action-button.active:active {
    background: var(--hemma-side-action-accent, var(--hemma-color-teal, #00c3d0));
    filter: brightness(1.12);
  }
}

card.--hemma-fan-animation:
[[[
  const s = String(entity?.state || '').toLowerCase();
  const isOn = s === 'on';
  const prev = this._hemmaPrevFan;
  this._hemmaPrevFan = isOn;
  const justOn  = isOn  && prev === false;
  const justOff = !isOn && prev === true;
  if (isOn) {
    return justOn
      ? 'hemma-fan-spin 1.5s ease-in 1, hemma-fan-spin 0.9s linear 1.5s infinite'
      : 'hemma-fan-spin 0.9s linear infinite';
  }
  if (justOff) return 'hemma-fan-coast 1.5s ease-out 1 forwards';
  return 'none';
]]]

