badges.--hemma-converge-init:
[[[
  if (!window._hemmaEnterPReg) {
    window._hemmaEnterPReg = true;
    try {
      CSS.registerProperty({
        name: '--hemma-badge-enter-p',
        syntax: '<number>',
        inherits: true,
        initialValue: '0'
      });
    } catch (e) {}
  }
  if (!window._hemmaMediaAnim) {
    window._hemmaMediaAnim = function (rootEl) {
      try {
        const row = rootEl.querySelector('#badges_media');
        if (!row) return;
        const SPRING = 'cubic-bezier(0.32, 0.72, 0, 1)';
        const OUT    = 'cubic-bezier(0.4, 0, 0.2, 1)';
        const dig = (el, out, d) => {
          if (!el || d > 8) return out;
          for (const c of Array.from(el.children || [])) {
            const t = c.localName === 'button-card' && c._config && c._config.template;
            if (t) { out.push(c); continue; }
            if (c.shadowRoot) dig(c.shadowRoot, out, d + 1);
            dig(c, out, d + 1);
          }
          return out;
        };
        requestAnimationFrame(() => {
          for (const b of dig(row, [], 0)) {
            const f = b.parentElement;
            if (!f || !f.id) continue;
            const op = parseFloat(
              getComputedStyle(b).getPropertyValue('--hemma-badge-opacity')) || 0;
            const vis = op > 0;
            if (b._hemmaVis === vis) continue;
            const first = b._hemmaVis === undefined;
            b._hemmaVis = vis;
            if (b._hemmaA) { b._hemmaA.cancel(); b._hemmaA = null; }
