              f.style.maxWidth = '';
              f.style.setProperty('--hemma-field-ovf', 'hidden');
              f._hemmaA = f.animate(
                [{ maxWidth: '0px', marginRight: '0px' },
                 { maxWidth: w + 'px', marginRight: gap + 'px' }],
                { duration: 420, easing: SPRING, fill: 'none' });
