card.extra_styles:
[[[
  const step = 22;

  const PC = window._hemmaPCSources?.(states, variables) || {};

  const fields = [
    ['mp1',  !!variables.media_player_1  && variables.media_player_1],
    ['mp2',  !!variables.media_player_2  && variables.media_player_2],
    ['mp3',  !!variables.media_player_3  && variables.media_player_3],
    ['mp4',  !!variables.media_player_4  && variables.media_player_4],
    ['mp5',  !!variables.media_player_5  && variables.media_player_5],
    ['mp6',  !!variables.media_player_6  && variables.media_player_6],
    ['mp7',  !!variables.media_player_7  && variables.media_player_7],
    ['mp8',  !!variables.media_player_8  && variables.media_player_8],
    ['mp9',  !!variables.media_player_9  && variables.media_player_9],
    ['mp10', !!variables.media_player_10 && variables.media_player_10],
    ['plex',   !!variables.plex_stream_1 && variables.plex_stream_1],
    ['plex_2', !!variables.plex_stream_2 && variables.plex_stream_2],
    ['activity1', !!variables.psn_1],
    ['activity2', !!variables.psn_2],
    ['activity_discord', !!PC.discord],
    ['activity_steam', !!PC.steam]
  ];

  let i = 0;
  let stagger = '';
  for (const [id, shown] of fields) {
    if (!shown) continue;
    stagger += '#' + id + '{--hemma-badge-enter-delay:' + (i * step) + 'ms;}';
    i++;
  }

  return (
    'ha-card{' +
      'will-change: auto !important;' +
      'isolation: auto !important;' +
      'contain: none !important;' +
    '}' +
    '#container{' +
      'will-change: auto !important;' +
      'isolation: auto !important;' +
    '}' +
    stagger +
    '#mp1, #mp2, #mp3, #mp4, #mp5, #mp6, #mp7, #mp8, #mp9, #mp10,' +
    '#plex, #plex_2, #activity1, #activity2, #activity_discord, #activity_steam{' +
      'overflow: var(--hemma-field-ovf, visible) !important;' +
    '}'
  );
]]]

