  const reg = (hass && hass.entities) || {};
  const devReg = (hass && hass.devices) || {};

  const siblingsOf = {};
  Object.keys(reg).forEach(id => {
    const dev = reg[id] && reg[id].device_id;
    if (!dev) return;
    (siblingsOf[dev] = siblingsOf[dev] || []).push(id);
  });

  const STRONG_DOMAINS = ['lock', 'cover', 'vacuum', 'camera', 'climate', 'fan', 'light', 'media_player', 'humidifier', 'valve', 'lawn_mower', 'water_heater'];

  const ICON_DOMAIN = {
    lock: 'lock',
    vacuum: 'vacuum',
    camera: 'camera|mdi:cctv',
    light: 'light',
    fan: 'fan',
    media_player: 'speaker',
    climate: 'thermostat',
    humidifier: 'humidifier',
    water_heater: 'hot_water',
    person: 'person',
    valve: 'valve|mdi:valve',
    lawn_mower: 'mower|mdi:robot-mower',
    remote: 'remote|mdi:remote',
    switch: 'plug',
    device_tracker: 'phone|mdi:cellphone',
  };

  const ICON_COVER_CLASS = {
    curtain: 'curtain-closed',
    blind: 'curtain-closed',
    shade: 'curtain-closed',
    shutter: 'curtain-closed',
    awning: 'curtain-closed',
    door: 'door-closed',
    garage: 'garage|mdi:garage',
    gate: 'gate|mdi:gate',
