    motion: 'motion',
    occupancy: 'motion',
    presence: 'person',
    door: 'door-closed',
    opening: 'door-closed',
    window: 'window|mdi:window-closed-variant',
    garage_door: 'garage|mdi:garage',
    moisture: 'leak|mdi:water-alert',
