    ['curtain|blind|shade|shutter', 'curtain-closed'],
    ['vacuum|roomba|robot', 'vacuum'],
    ['camera|cam\\b', 'camera|mdi:cctv'],
    ['motion|presence|occupancy|pir', 'motion'],
    ['thermostat|radiator|trv|climate', 'thermostat'],
    ['speaker|sonos|homepod|echo', 'speaker'],
