  };

  const deviceInfo = {};
  batteryEntityIds.forEach(id => { deviceInfo[id] = resolveDevice(id); });

  const cleanCardStyle = `
    :host {
      --ha-card-box-shadow:none !important;
      --button-card-box-shadow:none !important;
      --button-card-box-shadow-hover:none !important;
    }

    ha-card::before,
    ha-card::after,
    #card::before,
    #card::after,
    #container::before,
    #container::after {
      display:none !important;
    }

    ha-ripple {
      display:none !important;
    }

    ha-card {
      cursor: default !important;
    }

    @media (max-width:600px) {
      ha-card {
        padding-left:14px !important;
        padding-right:14px !important;
      }
    }
  `;

  const roomName = variables.room_name ?? 'Devices';

  const baseCardStyle = [
    { '--ha-card-box-shadow': 'none' },
    { '--button-card-box-shadow': 'none' },
    { '--button-card-box-shadow-hover': 'none' },
    { background: 'transparent' },
    { border: 'none' },
    { boxShadow: 'none' },
    { backdropFilter: 'none' },
    { WebkitBackdropFilter: 'none' },
  ];

  const headerCard = {
    type: 'custom:button-card',
    entity: batteryEntityIds[0],
    tap_action: { action: 'none' },
    show_icon: false,
    show_name: false,
    show_state: false,

    card_mod: { style: cleanCardStyle },

    styles: {
      card: [
        ...baseCardStyle,
        { padding: '28px' },
      ],
      grid: [
        { 'grid-template-areas': '"h"' },
        { 'grid-template-columns': '1fr' },
        { 'align-items': 'flex-start' },
      ],
      custom_fields: {
        h: [{ 'justify-self': 'stretch' }, { 'align-self': 'flex-start' }],
      },
    },

    custom_fields: {
      h: `[[[
        const roomName = ${JSON.stringify(roomName)};
        return '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary);text-align:left;">'
          + '<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;">' + roomName + '</div>'
          + '<div style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary);margin-top:2px;">Sensors \xb7 Batteries</div>'
        + '</div>';
      ]]]`,
    },
  };

  const RING_BOX = 58;
  const RING_STROKE = 5;
  const RING_R = (RING_BOX - RING_STROKE) / 2;

  const VS      = 4;
  const VB      = RING_BOX * VS;
  const VR      = RING_R * VS;
  const VSTROKE = RING_STROKE * VS;
  const RING_C  = 2 * Math.PI * VR;

  const BOLT_PATH  = 'M11 15H6L13 1V9H18L11 23V15Z';
  const BOLT_SCALE = 0.68;
  const BOLT_GAP   = 8;
  const BOLT_XF    = 'translate(' + (VB / 2) + ' ' + ((RING_BOX / 2 - RING_R) * VS)
    + ') scale(' + (BOLT_SCALE * VS) + ') translate(-12 -12)';

  const tileStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; padding: 0 !important; border-radius: 20px !important; cursor: pointer !important; overflow: visible !important; }',
    'ha-card::before, ha-card::after, ha-ripple { display: none !important; }',
    '#container, #c { overflow: visible !important; white-space: normal !important; }',
    '.hemma-ring-track, .hemma-ring-arc, .hemma-ring-bolt { transition: stroke 0.15s ease, fill 0.15s ease; }',
    '.hemma-ring-glyph { transition: background-color 0.15s ease, color 0.15s ease; }',
    '.hemma-ring-wrap { border-radius: 50%; transition: transform 0.15s ease; }',
    '.hemma-ring-wrap > * { pointer-events: none; }',
    '@media (hover: hover) { .hemma-ring-wrap:hover { transform: scale(1.03); --hemma-ring-track: var(--hemma-battery-ring-track-hover, rgba(255,255,255,0.125)); --hemma-ring-glyph: #ffffff; --hemma-ring-accent: color-mix(in srgb, var(--ring-accent-base, #ffffff) 80%, white); } }',
    '@media (hover: none) { ha-card:active .hemma-ring-wrap { transform: scale(1.03); --hemma-ring-track: var(--hemma-battery-ring-track-hover, rgba(255,255,255,0.125)); --hemma-ring-glyph: #ffffff; --hemma-ring-accent: color-mix(in srgb, var(--ring-accent-base, #ffffff) 80%, white); } }',
    '@keyframes hemmaRingDraw { from { stroke-dashoffset: var(--ring-c); } to { stroke-dashoffset: var(--ring-t); } }',
    '@keyframes hemmaRingFade { from { opacity: 0; } to { opacity: 1; } }',
    '.hemma-ring-arc { animation: hemmaRingDraw 0.7s cubic-bezier(0.22,1,0.36,1) var(--ring-delay,0s) both; }',
    '.hemma-ring-glyph, .hemma-ring-bolt { animation: hemmaRingFade 0.4s ease var(--ring-delay,0s) both; }',
  ].join('');

  const buildTile = (e, index) => {
    const info = deviceInfo[e.entity_id] || {};
    const icon = info.icon || 'battery';
    const isMdi = icon.indexOf(':') !== -1;
    const glyphUrl = isMdi
      ? ''
      : (typeof window.hemmaIconUrl === 'function'
          ? window.hemmaIconUrl(icon)
          : '/local/hemma/icons/' + icon + '.svg');

    const gsz = (icon.indexOf('lock') === 0 || icon === 'doorbell' || icon === 'light') ? '23.3px' : '22px';

    const glyph = isMdi
      ? '<ha-icon class="hemma-ring-glyph" icon="' + icon + '" style="--mdc-icon-size:22px;width:22px;height:22px;color:var(--hemma-ring-glyph, var(--hemma-popup-tiles-text-primary));display:block;"></ha-icon>'
      : '<div class="hemma-ring-glyph" style="width:' + gsz + ';height:' + gsz + ';background-color:var(--hemma-ring-glyph, var(--hemma-popup-tiles-text-primary));-webkit-mask:url(\'' + glyphUrl + '\') no-repeat center/contain;mask:url(\'' + glyphUrl + '\') no-repeat center/contain;"></div>';

    return {
      type: 'custom:button-card',
      entity: e.entity_id,
      tap_action: { action: 'more-info' },
      show_icon: false,
      show_name: false,
      show_state: false,
      extra_styles: tileStyle,

      styles: {
        card: [
          { background: 'transparent' },
          { border: 'none' },
          { boxShadow: 'none' },
          { padding: '0' },
        ],
        grid: [
          { 'grid-template-areas': '"c"' },
          { 'grid-template-columns': '1fr' },
        ],
        custom_fields: {
          c: [{ 'justify-self': 'stretch' }],
        },
      },

      custom_fields: {
        c: `[[[
          const s = states['${e.entity_id}'];
          const raw = parseFloat(s ? s.state : NaN);
          const known = !isNaN(raw) && s.state !== 'unavailable' && s.state !== 'unknown';
          const pct = known ? Math.max(0, Math.min(100, Math.round(raw))) : 0;
          const a = (s && s.attributes) || {};

          let charging = a.battery_state === 'charging'
            || a.device_power === 'charging'
            || a.power_state === 'charging'
            || a.is_charging === true
            || a.charging === true
            || (typeof a.icon === 'string' && a.icon.indexOf('battery-charging') !== -1);

          ${JSON.stringify(info.charge_ids || [])}.forEach(cid => {
            const cs = states[cid];
            if (!cs) return;
            const v = String(cs.state).trim().toLowerCase();
            if (cid.indexOf('binary_sensor.') === 0 && v === 'on') charging = true;
            if (cid.indexOf('sensor.') === 0 && (v === 'charging' || v === 'full')) charging = true;
            if (cid.indexOf('vacuum.') === 0 && (v === 'docked' || v === 'returning')) charging = true;
          });

          const accent = !known ? 'var(--hemma-popup-tiles-text-muted, rgba(255,255,255,0.52))'
            : pct <= 10 ? 'var(--hemma-battery-red,#FF4245)'
            : pct <= 20 ? 'var(--hemma-battery-yellow,#FFD600)'
            : 'var(--hemma-battery-green,#30D158)';

          const ringC = ${RING_C.toFixed(2)};
          const target = (ringC - (pct / 100) * ringC).toFixed(2);
          const delay = ${(index * 0.04).toFixed(2)};
          const maskId = 'ring_${e.entity_id.replace(/[^a-z0-9]/gi, '_')}';

          const notch = charging
            ? '<path d="${BOLT_PATH}" transform="${BOLT_XF}" fill="#000" stroke="#000" stroke-width="${BOLT_GAP}" stroke-linejoin="round" stroke-linecap="round"/>'
            : '';

          const arc = (known && pct > 0)
            ? '<circle class="hemma-ring-arc" cx="${VB / 2}" cy="${VB / 2}" r="${VR}" fill="none" stroke="var(--hemma-ring-accent, var(--ring-accent-base))" stroke-width="${VSTROKE}" stroke-linecap="round" transform="rotate(-90 ${VB / 2} ${VB / 2})" style="stroke-dasharray:' + ringC + ';--ring-c:' + ringC + ';--ring-t:' + target + ';--ring-delay:' + delay + 's;"/>'
            : '';

          const bolt = charging
            ? '<path class="hemma-ring-bolt" d="${BOLT_PATH}" transform="${BOLT_XF}" fill="var(--hemma-ring-accent, var(--ring-accent-base))" style="--ring-delay:' + delay + 's;"/>'
            : '';

          const pctText = known ? pct + '%' : '\\u2014';
          const pctColor = (known && pct <= 20)
            ? accent
            : 'var(--hemma-popup-tiles-text-primary)';

          return '<div style="display:flex;flex-direction:column;align-items:center;gap:8px;font-family:var(--primary-font-family,system-ui);">'
            + '<div class="hemma-ring-wrap" style="position:relative;width:${RING_BOX}px;height:${RING_BOX}px;display:flex;align-items:center;justify-content:center;--ring-accent-base:' + accent + ';">'
              + '<svg width="${RING_BOX}" height="${RING_BOX}" viewBox="0 0 ${VB} ${VB}" style="position:absolute;inset:0;display:block;overflow:visible;">'
                + '<defs><mask id="' + maskId + '" maskUnits="userSpaceOnUse" x="${-14 * VS}" y="${-14 * VS}" width="${VB + 28 * VS}" height="${VB + 28 * VS}" color-interpolation="sRGB"><rect x="${-14 * VS}" y="${-14 * VS}" width="${VB + 28 * VS}" height="${VB + 28 * VS}" fill="#fff"/>' + notch + '</mask></defs>'
                + '<g mask="url(#' + maskId + ')">'
                  + '<circle class="hemma-ring-track" cx="${VB / 2}" cy="${VB / 2}" r="${VR}" fill="none" stroke="var(--hemma-ring-track, var(--hemma-popup-progress-track, rgba(255,255,255,0.09)))" stroke-width="${VSTROKE}"/>'
                  + arc
                + '</g>'
                + bolt
              + '</svg>'
              + '<div style="position:relative;display:flex;align-items:center;justify-content:center;">' + ${JSON.stringify(glyph)} + '</div>'
            + '</div>'
            + '<div style="display:flex;flex-direction:column;align-items:center;gap:1px;width:100%;">'
              + '<span style="font-size:15px;font-weight:700;letter-spacing:-0.01em;color:' + pctColor + ';line-height:1.25;">' + pctText + '</span>'
              + '<span style="font-size:12px;font-weight:400;line-height:1.25;min-height:27px;color:var(--hemma-popup-tiles-text-secondary);text-align:center;width:100%;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;">' + ${JSON.stringify(info.name || '')} + '</span>'
            + '</div>'
          + '</div>';
        ]]]`,
      },
    };
  };

  let tilesCard = null;

  if (allBatteries.length > 0) {
    const fields = {};
    const fStyles = {};

    const tileIds = allBatteries.map((e, i) => '#s' + i);

    fields.gridcss = '<style>'
      + '#container { grid-template-areas: none !important; grid-auto-flow: row !important; }'
      + tileIds.join(',') + ' { grid-area: auto !important; overflow: visible !important; white-space: normal !important; }'
      + '@media (max-width: 620px) { #container { grid-template-columns: repeat(3, minmax(0,1fr)) !important; } }'
      + '</style>';
    fStyles.gridcss = [{ display: 'none' }];

    allBatteries.forEach((e, i) => {
      fields['s' + i] = { card: buildTile(e, i) };
      fStyles['s' + i] = [{ 'justify-self': 'stretch' }];
    });

    tilesCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false,
      show_name: false,
      show_state: false,

      card_mod: { style: cleanCardStyle },

      styles: {
        card: [
          ...baseCardStyle,
          { padding: '4px 24px 26px 24px' },
        ],
        grid: [
          { 'grid-template-areas': 'none' },
          { 'grid-template-columns': 'repeat(4, minmax(0,1fr))' },
          { gap: '20px 4px' },
          { 'align-items': 'start' },
        ],
        custom_fields: fStyles,
      },

      custom_fields: fields,
    };
  }

  const emptyCard = {
    type: 'custom:button-card',
    tap_action: { action: 'none' },
    show_icon: false,
    show_name: false,
    show_state: false,

    card_mod: { style: cleanCardStyle },

    styles: {
      card: [
        ...baseCardStyle,
        { padding: '20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': '"m"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: {
        m: [{ 'justify-self': 'center' }],
      },
    },

    custom_fields: {
      m: `
        <div style="color:var(--hemma-popup-tiles-text-muted);font-size:14px;text-align:center;">
          No battery sensors found
        </div>
      `,
    },
  };

  return {
    type: 'vertical-stack',
    cards: [
      headerCard,
      tilesCard || emptyCard,
    ],
  };
]]]

hemma_camera_alert_helper.value:
[[[
  if (typeof window.hemmaCameraAlert !== 'function') {
    /* Ring publishes ding/motion as event.* entities whose state is the
       timestamp of the last one, so "recent" is the whole alert model.
       Reading sensor.time subscribes the caller to the minute tick, which
       is what lets a stale alert expire without another camera event. */
    window.hemmaCameraAlert = function (hass, states, cams, windowMinutes) {
      const reg = (hass && hass.entities) || {};
      const devs = {};
      cams.forEach(function (id) {
        const d = reg[id] && reg[id].device_id;
        if (d) devs[d] = true;
      });
      const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
      const now = Date.now();
      states['sensor.time'];
      let ding = false, motion = false;
      Object.keys(reg).forEach(function (id) {
        if (id.indexOf('event.') !== 0) return;
        if (!devs[reg[id].device_id]) return;
        const t = Date.parse(states[id] && states[id].state);
        if (!isFinite(t) || now - t > span) return;
        if (/ding|doorbell|button/.test(id)) ding = true;
        else if (/motion/.test(id)) motion = true;
      });
      return ding ? 'Doorbell' : motion ? 'Motion Detected' : '';
    };
  }
  return true;
]]]

