data.content:
[[[
  const reg    = (hass && hass.entities) || {};
  const nameOv = variables.camera_names || {};
  const actOv  = variables.activity_entities || {};
  const exclude = Array.isArray(variables.exclude) ? variables.exclude : [];

  /* Candidate ids come from the registry, never Object.values(states) —
     that Proxy walk subscribes this card to every entity in the house. */
  let ids;
  if (Array.isArray(variables.cameras) && variables.cameras.length) {
    ids = variables.cameras.filter(Boolean);
  } else {
    ids = Object.keys(reg).filter(id => {
      if (!id.startsWith('camera.')) return false;
      const r = reg[id] || {};
      if (r.hidden || r.hidden_by || r.entity_category) return false;
      if (r.platform === 'browser_mod') return false;
      if (/_last_recording$/.test(id)) return false;
      return true;
    });
  }
  ids = ids.filter(id => !exclude.includes(id));

  const cams = ids.map(id => ({ id: id, s: states[id] })).filter(c => c.s);

  const TPL = 21;

  /* Owns the selected camera, the live card and its hass pump.
     Only one stream is ever mounted; the grid stays on stills. */
  if (window._hemmaCAMv !== TPL) {
    window._hemmaCAMv = TPL;
    window._hemmaCAM = {
      _card: null, _timer: null,

      _ha: function () { return document.querySelector('home-assistant'); },

      svc: function (domain, service, data) {
        const ha = this._ha();
        if (ha && ha.hass) ha.hass.callService(domain, service, data);
      },

      /* Mobile: the popup's swipe-dismiss handler claims touchstart, so the
         browser never synthesises a click and onclick alone never fires. Every
         control acts on touchend instead; whichever event lands first wins and
         the other is dropped inside the 900ms window. */
      act: function (event, el, name, arg) {
        if (event) {
          if (event.type === 'touchend') {
            this._lt = Date.now();
            if (event.cancelable) event.preventDefault();
          } else if (this._lt && Date.now() - this._lt < 900) {
            return;
          }
        }
        if (name === 'open') {
          if (this.holdConsumed()) return;
          this.open(arg, el);
        }
        else if (name === 'back') this.back(el);
        else if (name === 'mute') this.toggleMute(el);
        else if (name === 'fit')  this.toggleFit(el);
        else if (name === 'rec')  this.toggleRecording(arg, el);
        else if (name === 'acc')  this.accToggle(arg, el);
        else if (name === 'fs')   this.fullscreen(el);
        else if (name === 'info') this.moreInfo(arg);
      },

      /* Tap opens the camera in this popup; hold hands off to HA's own
         more-info, so both routes out of the grid are available. */
      holdPoint: function (event) {
        if (!event) return null;
        const t = event.touches && event.touches[0];
        const x = t ? t.clientX : event.clientX;
        const y = t ? t.clientY : event.clientY;
        return (x === undefined || x === null) ? null : [x, y];
      },

      /* brightness, never transform: open() measures the tile to start the
         zoom, and a scaled tile would hand it the wrong rect. */
      holdPaint: function (on) {
        const el = this._holdEl;
        if (el && el.style) el.style.filter = on ? 'brightness(0.93)' : '';
      },

      holdEnd: function () {
        if (this._holdT) { clearTimeout(this._holdT); this._holdT = null; }
        this.holdPaint(false);
      },

      holdStart: function (event, el, camId) {
        const self = this;
        self.holdEnd();
        self._holdEl = el;
        self._holdFired = false;
        self._holdXY = self.holdPoint(event);
        self.holdPaint(true);
        self._holdT = setTimeout(function () {
          self._holdT = null;
          self._holdFired = true;
          self.holdPaint(false);
          self.moreInfo(camId);
        }, 480);
      },

      holdMove: function (event) {
        if (!this._holdT || !this._holdXY) return;
        const p = this.holdPoint(event);
        if (!p) return;
        if (Math.abs(p[0] - this._holdXY[0]) > 10 || Math.abs(p[1] - this._holdXY[1]) > 10) {
          this._holdFired = false;
          this.holdEnd();
        }
      },

      /* True once the press has already become a hold, so the tap that
         follows it is dropped rather than opening the camera too. */
      holdConsumed: function () {
        this.holdEnd();
        if (!this._holdFired) return false;
        this._holdFired = false;
        return true;
      },

      /* A one-camera popup has nothing to pick from, so it opens straight on
         the live view. Fired from a 1x1 data-URI image's onload: the element is
         in the DOM by then, which is what gives us something to climb from. */
      autoOpen: function (el, camId) {
        const root = el && el.closest('.hemma-cam-root');
        if (!root || root.dataset.hemmaAuto) return;
        root.dataset.hemmaAuto = '1';
        const detail = root.querySelector('.cam-detail[data-cam="' + camId + '"]');
        const mount = detail && detail.querySelector('.cam-stream-mount');
        if (!mount) return;
        this._fit = 'cover';
        this._muted = true;
        this.mount(camId, mount);
        this.paintFit(detail);
      },

      moreInfo: function (id) {
        const ha = this._ha();
        if (!ha) return;
        ha.dispatchEvent(new CustomEvent('hass-more-info', {
          bubbles: true, composed: true, detail: { entityId: id },
        }));
      },

      /* videoWidth is unknown until metadata lands, and the scale factor needs it.
         Show the still until the video can be revealed already zoomed. */
      settle: function () {
        const self = this;
        if (self._poll) clearInterval(self._poll);
        let n = 0;
        self._poll = setInterval(function () {
          n++;
          const v = self.video();
          if (v) {
            if (!v.dataset.hemmaHeld) {
              v.dataset.hemmaHeld = '1';
              v.style.opacity = '0';
            }
            if ((v.videoWidth && v.videoHeight) || v.readyState >= 2) {
              self.applyFit(false);
              self.applyAudio();
              v.style.opacity = '1';
              self.clearBackdrop();
              clearInterval(self._poll); self._poll = null;
              return;
            }
          }
          /* Give up after 5s and drop the still regardless: a placeholder that
             outlives the poll reads as a permanently out-of-focus camera. */
          if (n > 50) {
            if (v) v.style.opacity = '1';
            self.clearBackdrop();
            clearInterval(self._poll); self._poll = null;
          }
        }, 100);
      },

      /* The tile still is painted onto the mount as a placeholder. Once the
         stream is up it would show through the letterbox bars in contain mode,
         so it has to come off as soon as the video is visible. */
      clearBackdrop: function () {
        if (this._mount) this._mount.style.backgroundImage = '';
      },

      teardown: function () {
        this._playing = false;
        if (this._poll) { clearInterval(this._poll); this._poll = null; }
        if (this._raf) { cancelAnimationFrame(this._raf); this._raf = null; }
        if (this._audT) { clearTimeout(this._audT); this._audT = null; }
        if (this._recT) { clearTimeout(this._recT); this._recT = null; }
        if (this._probeT) { clearTimeout(this._probeT); this._probeT = null; }
        if (this._probe) { try { this._probe.remove(); } catch (e) {} this._probe = null; }
        this._mount = null;
        if (this._timer) { clearInterval(this._timer); this._timer = null; }
        if (this._card) { try { this._card.remove(); } catch (e) {} this._card = null; }
      },

      mount: function (camId, mountEl) {
        const self = this;
        self.teardown();
        self._mount = mountEl;
        self._modeText = 'Live';
        const ha = self._ha();
        if (!ha || !mountEl) return;

        /* Building a picture-entity is what pulls in hui-image, and with it
           ha-camera-stream. We throw the card away and mount the player
           ourselves: hui-image hardcodes `muted`, and ha-camera-stream reads
           that flag when it PICKS a stream, not just to set volume — muted
           lets it settle on WebRTC, which for Ring has no audio track at all.
