    ids = variables.cameras.filter(Boolean);
  } else {
    ids = Object.keys(reg).filter(id => {
      if (!id.startsWith('camera.')) return false;
      const r = reg[id] || {};
      if (r.hidden || r.hidden_by || r.entity_category) return false;
      if (r.platform === 'browser_mod') return false;
