        if (this._recT) { clearTimeout(this._recT); this._recT = null; }
        if (this._probeT) { clearTimeout(this._probeT); this._probeT = null; }
        if (this._probe) { try { this._probe.remove(); } catch (e) {} this._probe = null; }
