        if (this._timer) { clearInterval(this._timer); this._timer = null; }
        if (this._card) { try { this._card.remove(); } catch (e) {} this._card = null; }
      },

      mount: function (camId, mountEl) {
        const self = this;
        self.teardown();
        self._mount = mountEl;
        self._modeText = 'Live';
        const ha = self._ha();
        if (!ha || !mountEl) return;

        /* Building a picture-entity is what pulls in hui-image, and with it
           ha-camera-stream. We throw the card away and mount the player
           ourselves: hui-image hardcodes `muted`, and ha-camera-stream reads
           that flag when it PICKS a stream, not just to set volume — muted
