        const btns = scope ? scope.querySelectorAll('.cam-fit') : [];
        for (let i = 0; i < btns.length; i++) {
          const b = btns[i];
          const ic = b.querySelector('ha-icon');
          b.setAttribute('data-tip', on ? 'Zoom to Fit' : 'Zoom to Fill');
          this.mark(b, on);
          b.style.background = on ? 'rgba(255,255,255,0.92)' : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
          b.style.color = on ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
          if (ic) {
            ic.setAttribute('icon', on ? 'mdi:overscan' : 'mdi:fit-to-screen-outline');
