        self._muted = self._muted === false;
        self.applyAudio();
        const scope = el.closest('.cam-detail');
        if (!scope) return;
        self.syncAudio(scope);
        if (self._audT) { clearTimeout(self._audT); self._audT = null; }
        self.setMode(scope, self._modeText || 'Live');
        if (self._muted) return;
        /* audioTracks/webkitAudioDecodedByteCount are both empty until the
           decoder has actually run, so an immediate verdict always reads
           "no audio" even when there is some. */
        self._audT = setTimeout(function () {
          self._audT = null;
          if (self._muted === false && !self.hasAudio()) {
            self.setMode(scope, (self._modeText || 'Live') + ' \xb7 no audio');
          }
        }, 1500);
      },

      /* Apple's gesture: tap the picture to fill the screen. The frame goes,
         not the <video>, so the rounded mask and the aspect box travel with it.
         iOS has no element fullscreen — there only the video can go. */
      /* The browser can leave fullscreen without us — Esc, the system gesture,
         iOS's own Done button — so the glyph follows the document, not our call. */
      paintFs: function () {
        const on = !!(document.fullscreenElement || document.webkitFullscreenElement);
        const scope = this._fsScope;
        const b = scope && scope.querySelector('.cam-fs');
        const ic = b && b.querySelector('ha-icon');
        if (ic) ic.setAttribute('icon', on ? 'mdi:arrow-collapse' : 'mdi:arrow-expand');
      },

      watchFs: function () {
        if (this._fsBound) return;
        this._fsBound = true;
        const self = this;
        const upd = function () { self.paintFs(); };
        document.addEventListener('fullscreenchange', upd);
        document.addEventListener('webkitfullscreenchange', upd);
      },

      fullscreen: function (el) {
        const scope = el.closest('.cam-detail');
        this._fsScope = scope;
        this.watchFs();
        const box = scope && scope.querySelector('.cam-frame');
        const d = document;
        if (d.fullscreenElement || d.webkitFullscreenElement) {
          if (d.exitFullscreen) d.exitFullscreen();
          else if (d.webkitExitFullscreen) d.webkitExitFullscreen();
          return;
        }
        const landscape = function () {
          try {
            const o = window.screen && window.screen.orientation;
            if (o && o.lock) {
              const p = o.lock('landscape');
              if (p && p.catch) p.catch(function () {});
            }
          } catch (e) {}
        };

        const req = box && (box.requestFullscreen || box.webkitRequestFullscreen);
        if (req) {
          try {
            const r = req.call(box);
            if (r && r.then) r.then(landscape, function () {});
            else landscape();
            return;
          } catch (e) {}
        }
        const v = this.video();
        if (v && v.webkitEnterFullscreen) v.webkitEnterFullscreen();
      },

      accState: function (id) {
        const ha = this._ha();
        const st = ha && ha.hass && ha.hass.states[id];
        if (!st) return null;
        const v = String(st.state).toLowerCase();
        if (id.indexOf('lock.') === 0) return v === 'unlocked' ? 'open' : 'shut';
        if (id.indexOf('cover.') === 0) return (v === 'open' || v === 'opening') ? 'open' : 'shut';
        if (id.indexOf('alarm_control_panel.') === 0) return v === 'disarmed' ? 'shut' : 'open';
        return v === 'on' ? 'open' : 'shut';
      },

      /* A pill is content-width, and auto can't be transitioned. Measure the
         old and new widths around the swap, animate between the two numbers,
         then hand the width back to the content. */
      morph: function (el, paint) {
        const from = el.getBoundingClientRect().width;
        el.style.transition = 'none';
        el.style.width = 'auto';
        el.style.overflow = '';
        paint();
        const to = el.getBoundingClientRect().width;
        if (!from || !to || Math.abs(to - from) < 0.5) {
          el.style.width = '';
          el.style.transition = 'background-color 260ms ease, color 260ms ease, box-shadow 180ms ease';
          return;
        }
        /* Clipped only while the label slides in — left on, it would cut the
           hover tooltip off at the pill's edge. */
        el.style.overflow = 'hidden';
        el.style.width = from + 'px';
        el.getBoundingClientRect();
        el.style.transition = 'width 420ms cubic-bezier(0.34,1.42,0.52,1),'
          + ' background-color 260ms ease, color 260ms ease';
        el.style.width = to + 'px';
        if (el._morphT) clearTimeout(el._morphT);
        el._morphT = setTimeout(function () {
          el._morphT = null;
          el.style.transition = 'background-color 260ms ease, color 260ms ease, box-shadow 180ms ease';
          el.style.width = '';
          el.style.overflow = '';
        }, 440);
      },

      /* One tap on the siren wakes the building, so it arms a confirm state
         and fires on the second tap. */
      needsConfirm: function (id) {
        return id.indexOf('siren.') === 0 || id.indexOf('alarm_control_panel.') === 0;
      },

      confirmLabel: function (id, open) {
        if (id.indexOf('siren.') === 0) return open ? 'Stop siren?' : 'Sound siren?';
        return open ? 'Disarm?' : 'Arm away?';
      },

      clearConfirm: function () {
        if (this._cfT) { clearTimeout(this._cfT); this._cfT = null; }
        const el = this._cfEl;
        this._cfEl = null;
        if (!el) return;
        el.removeAttribute('data-confirm');
        this.paintAcc(el, this.accState(el.getAttribute('data-acc')));
      },

      armConfirm: function (id, el) {
        const self = this;
        self.clearConfirm();
        el.setAttribute('data-confirm', '1');
        self._cfEl = el;
        self.mark(el, true);

        self.morph(el, function () {
          el.style.background = 'var(--hemma-popup-orange-color, #ff9230)';
          el.style.color = '#1c1c1e';
          const ic = el.querySelector('ha-icon');
          const tx = el.querySelector('span');
          if (ic) { ic.setAttribute('icon', 'mdi:alert-outline'); ic.style.color = '#1c1c1e'; }
          if (tx) {
            tx.textContent = self.confirmLabel(id, self.accState(id) === 'open');
            tx.style.display = '';
          }
          el.removeAttribute('data-tip');
        });

        self._cfT = setTimeout(function () { self._cfT = null; self.clearConfirm(); }, 5000);
      },

      accToggle: function (id, el) {
        const cur = this.accState(id);
        if (cur === null) return;
        if (this.needsConfirm(id) && el.getAttribute('data-confirm') !== '1') {
          this.armConfirm(id, el);
          return;
        }
        if (this._cfT) { clearTimeout(this._cfT); this._cfT = null; }
        this._cfEl = null;
        el.removeAttribute('data-confirm');
        const open = cur === 'open';
        if (id.indexOf('lock.') === 0)        this.svc('lock', open ? 'lock' : 'unlock', { entity_id: id });
        else if (id.indexOf('cover.') === 0)  this.svc('cover', open ? 'close_cover' : 'open_cover', { entity_id: id });
        else if (id.indexOf('alarm_control_panel.') === 0)
          this.svc('alarm_control_panel', open ? 'alarm_disarm' : 'alarm_arm_away', { entity_id: id });
        else                                  this.svc('homeassistant', open ? 'turn_off' : 'turn_on', { entity_id: id });
        this.paintAcc(el, open ? 'shut' : 'open');
        const self = this;
        setTimeout(function () { self.paintAcc(el, self.accState(id)); }, 1400);
      },

      paintAcc: function (el, state) {
        if (!el || !state) return;
        const open = state === 'open';
        const self = this;
        self.mark(el, open);
        self.morph(el, function () {
          el.style.background = open ? 'rgba(255,255,255,0.92)' : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
          el.style.color = open ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
          const ic = el.querySelector('ha-icon');
          const tx = el.querySelector('span');
          const on = el.getAttribute('data-icon-open'), off = el.getAttribute('data-icon-shut');
          const txt = open ? (el.getAttribute('data-label-open') || '') : '';
          if (ic) { ic.setAttribute('icon', open ? on : off); ic.style.color = open ? '#1c1c1e' : 'rgba(255,255,255,0.92)'; }
          if (tx) { tx.textContent = txt; tx.style.display = txt ? '' : 'none'; }
          /* A tooltip repeating a label the pill is already showing is noise. */
          if (txt) el.removeAttribute('data-tip');
          else el.setAttribute('data-tip', el.getAttribute('data-label-shut') || '');
        });
      },

      /* One button owns playback: it lights up while the recording runs and
         the next tap drops back to live, so there is no second "go live"
         control needing room in the row. */
      toggleRecording: function (recId, el) {
        const scope = el.closest('.cam-detail');
        const camId = scope && scope.getAttribute('data-cam');
        if (this._playing) { this.goLive(camId, el); return; }
        if (this._probe) {
          /* Still loading. Live never stopped, so dropping the probe is enough. */
          try { this._probe.remove(); } catch (e) {}
          this._probe = null;
          if (this._probeT) { clearTimeout(this._probeT); this._probeT = null; }
          this.paintRec(scope, false);
          return;
        }
        this.playRecording(recId, el);
      },

      /* Live is still running underneath, so just say so and put the header back. */
      unavailable: function (scope) {
        const self = this;
        self.setMode(scope, 'Recording unavailable');
        if (self._recT) clearTimeout(self._recT);
        self._recT = setTimeout(function () {
          self._recT = null;
          self.setMode(scope, self._modeText || 'Live');
        }, 1800);
      },

      paintRec: function (scope, playing) {
        const b = scope && scope.querySelector('.cam-rec');
        if (!b) return;
        const ic = b.querySelector('ha-icon');
        b.style.background = playing
          ? 'rgba(255,255,255,0.92)'
          : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
        b.style.color = playing ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
        b.setAttribute('data-tip', playing ? 'Live' : 'Last Recording');
        this.mark(b, playing);
        if (ic) ic.style.color = playing ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
      },

      /* Plays the recording in the same frame — no second dialog. The clip
         loads behind the live stream and only swaps in once it can actually
         play, so a recording that never arrives costs nothing on screen. */
      playRecording: function (recId, el) {
        const self = this;
        const scope = el.closest('.cam-detail');
        const ha = self._ha();
        const st = ha && ha.hass && ha.hass.states[recId];
        const url = st && st.attributes && st.attributes.video_url;
        const mount = scope && scope.querySelector('.cam-stream-mount');
        if (!mount) return;
        if (!url) { self.unavailable(scope); return; }

        const v = document.createElement('video');
        v.src = url; v.controls = true; v.playsInline = true; v.preload = 'auto';
        v.muted = self._muted !== false;
        v.setAttribute('playsinline', '');
