          + 'object-fit:contain;background:#000;display:block;z-index:3;'
          + 'opacity:0;transition:opacity 180ms ease;';
        mount.appendChild(v);
        self._probe = v;
        self.paintRec(scope, true);

        let done = false;
        const fail = function () {
          if (done) return; done = true;
          if (self._probeT) { clearTimeout(self._probeT); self._probeT = null; }
          if (self._probe === v) self._probe = null;
          try { v.remove(); } catch (e) {}
          self.paintRec(scope, false);
          self.unavailable(scope);
        };
        const ready = function () {
          if (done) return; done = true;
          if (self._probeT) { clearTimeout(self._probeT); self._probeT = null; }
          self._probe = null;
          self.teardown();
          self._mount = mount;
          self._card = v;
          self._playing = true;
          self.clearBackdrop();
          v.style.opacity = '1';
          const pl = v.play();
          if (pl && pl.catch) pl.catch(function () {});
