           button lit forever. */
        self._probeT = setTimeout(fail, 8000);
      },

      goLive: function (camId, el) {
        const scope = el.closest('.cam-detail');
        const mount = scope && scope.querySelector('.cam-stream-mount');
        if (this._recT) { clearTimeout(this._recT); this._recT = null; }
        this.mount(camId, mount);
        this._modeText = 'Live';
        this.setMode(scope, 'Live');
        this.paintRec(scope, false);
      },

      setMode: function (scope, txt) {
        const el = scope && scope.querySelector('.cam-mode');
        if (el) el.textContent = txt;
      },

    };
  }

  /* Bump TPL on any edit to the markup or to _hemmaCAM. The cached render is
     keyed on entity state alone, so without it a soft reload keeps serving the
