  const _ck = 'hemma_cams_' + TPL + '_' + (entity?.entity_id || 'x');
  const _ch = cams.map(c => [c.id, c.s.state, c.s.attributes?.entity_picture, c.s.last_changed].join(':')).join('|')
    + '|' + Object.keys(reg).length + '|' + window.innerWidth;
  window._hc = window._hc || {};
  if (window._hc[_ck]?.h === _ch) return window._hc[_ck].r;

  const esc = s => String(s ?? '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');

  const resolveUrl = raw => {
    if (!raw) return '';
    const s = String(raw);
    return s.startsWith('/') ? location.origin + s : s;
  };

  const siblingsOf = {};
  Object.keys(reg).forEach(id => {
    const dev = reg[id] && reg[id].device_id;
