  };

  /* Apple's tile stamp: bare "11s" / "2m" / "3h", no "ago". */
  const stamp = ms => {
    if (!isFinite(ms) || ms < 0) return '';
    const s = ms / 1000;
    if (s < 60)    return Math.max(1, Math.floor(s)) + 's';
    if (s < 3600)  return Math.floor(s / 60) + 'm';
    if (s < 86400) return Math.floor(s / 3600) + 'h';
    return Math.floor(s / 86400) + 'd';
  };

  const ageMsOf = cam => {
    const act = activityOf(cam.id);
    const raw = act ? states[act]?.state : null;
    const t = raw ? Date.parse(raw) : Date.parse(cam.s.last_changed);
    return isFinite(t) ? Date.now() - t : NaN;
