     last_recording camera usually still has one. */
  const fallbackOf = camId => {
    const alt = camId.replace(/_live_view$/, '_last_recording');
    const pick = (id) => (id && id !== camId && states[id]?.attributes?.entity_picture)
      ? resolveUrl(states[id].attributes.entity_picture) : '';
