  const gridStyle = wrapperStyle + `
    ha-card #container { display: block !important; padding: 0 !important; width: 100% !important; }
    .hemma-cam-tile img { transition: transform 0.35s ease, filter 0.2s ease; }
    .hemma-back-glass { position: relative; width: 34px; height: 34px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center; flex: 0 0 auto;
      cursor: pointer; pointer-events: auto;
