      background-color: rgba(255,255,255,0.07);
      background-image: radial-gradient(140% 90% at 50% -20%, rgba(255,255,255,0.14), rgba(255,255,255,0.04) 45%, transparent 62%);
      backdrop-filter: blur(10px) saturate(1.2); -webkit-backdrop-filter: blur(10px) saturate(1.2); }
    .hemma-back-glass::before { content: ""; position: absolute; inset: 0; border-radius: 50%; padding: 1.4px;
      background: conic-gradient(from 0deg, rgba(255,255,255,0.55) 0deg, rgba(255,255,255,0.12) 55deg,
        rgba(255,255,255,0.02) 90deg, rgba(255,255,255,0.12) 130deg, rgba(255,255,255,0.30) 175deg 185deg,
        rgba(255,255,255,0.12) 230deg, rgba(255,255,255,0.02) 270deg, rgba(255,255,255,0.12) 305deg,
        rgba(255,255,255,0.55) 360deg);
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      mask-composite: exclude; pointer-events: none; }
    .hemma-back-glass::after { content: ""; position: absolute; inset: -1px; border-radius: 50%; padding: 1px;
      background: conic-gradient(from 0deg, transparent 0deg 50deg, rgba(0,0,0,0.32) 80deg 100deg,
        transparent 130deg 230deg, rgba(0,0,0,0.32) 260deg 280deg, transparent 310deg 360deg);
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      mask-composite: exclude; pointer-events: none; }
    .hemma-back-glass:active { transform: scale(0.94); }
