data.content:
[[[
  const sensors  = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];
  const tempId   = variables.entity_temp;
  const humidId  = variables.entity_humidity;
  const qualId   = variables.entity_quality || sensors[0] || entity?.entity_id;
  const roomName = variables.room_name || 'Climate';

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id]?.state;
    if (!s || s === 'unavailable' || s === 'unknown') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const sensorThresh = (eid) => {
    const id   = (eid || '').toLowerCase();
    const unit = states[eid]?.attributes?.unit_of_measurement || '';
    const dc   = (states[eid]?.attributes?.device_class || '').toLowerCase();
    const isIndex = id.endsWith('_index') || unit.toLowerCase() === 'index';
    if (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25')
      return { good: 12,   moderate: 35.4, high: 55.4, unit: unit || 'µg/m³' };
    if (id.includes('pm10') || dc === 'pm10')
      return { good: 54,   moderate: 154,  high: 254,  unit: unit || 'µg/m³' };
    if (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic'))
      return isIndex
        ? { good: 6,   moderate: 8,   high: 9,   unit: unit || 'index' }
        : { good: 100, moderate: 200, high: 300, unit: unit || 'ppb' };
    if (id.includes('no2') || id.includes('nitrogen_dioxide') || dc === 'nitrogen_dioxide')
      return isIndex
        ? { good: 6,  moderate: 8,   high: 9,   unit: unit || 'index' }
        : { good: 53, moderate: 100, high: 360, unit: unit || 'ppb' };
    if (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide')
      return { good: 1000, moderate: 1500, high: 2000, unit: unit || 'ppm' };
    return { good: null, moderate: null, high: null, unit };
  };

  const _qid  = JSON.stringify(qualId  || '');
  const _tid  = JSON.stringify(tempId  || '');
  const _hid  = JSON.stringify(humidId || '');
  const _sns  = JSON.stringify(sensors);
  const _room = JSON.stringify(roomName);

  const allEntities = [qualId, tempId, humidId, ...sensors].filter(Boolean);

  const temp      = safeNum(tempId);
  const tempUnit  = states[tempId]?.attributes?.unit_of_measurement || '°';
  const isFahrenheit = tempUnit === '°F';
  const graphTempColor =
    temp == null ? '#67F5A0' :
    isFahrenheit ? (
      temp < 76 ? '#67F5A0' :
      temp < 82 ? '#FF9230' : '#FF4245'
    ) : (
      temp < 24 ? '#67F5A0' :
      temp < 28 ? '#FF9230' : '#FF4245'
    );

  // Tooltip time format
  const _tf = hass?.locale?.time_format;
  const _use12hr = _tf === '12' || (_tf !== '24' && new Intl.DateTimeFormat(hass?.locale?.language || 'en', { hour: 'numeric' }).resolvedOptions().hour12);
  const tooltipTimeFormat = _use12hr ? 'h:mm tt' : 'HH:mm';

  /* Styles */

  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; border-color: transparent !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    '#container { overflow: visible !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; pointer-events: auto !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; }',
    'ha-card #container { transition: opacity 0.18s ease, filter 0.18s ease !important; }',
    'ha-card:hover #container { filter: brightness(1.12) saturate(1.08) drop-shadow(0 0 10px rgba(255,255,255,0.05)); }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }',
    'ha-card { background: var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--hemma-popup-tile-hover-duration, 0.2s) ease, transform var(--hemma-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    'ha-card:hover { background: var(--hemma-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--hemma-popup-tile-hover-scale, 1.01)) !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  /* card_mod lands too late to hide the empty chart shell, so the
     entrance animation runs from apex_config instead. EVAL: is
     apexcharts-card's hook for a function in a serialised config. */
  const chartEnter = 'EVAL:' + [
    'function (ctx) {',
    '  try {',
    '    var graph = ctx && ctx.el;',
    '    if (!graph || (ctx.w && ctx.w.globals && ctx.w.globals.noData)) return;',
    '    var wrap = graph.closest("#graph-wrapper") || graph.parentElement;',
    '    if (!wrap || !graph.animate || wrap.dataset.hemmaChartEntered) return;',
    '    wrap.dataset.hemmaChartEntered = "1";',
    '    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {',
    '      graph.animate([{ opacity: 0 }, { opacity: 1 }],',
    '        { duration: 200, easing: "ease-out", fill: "backwards" });',
    '      return;',
    '    }',
    '    /* squash, not lift, drives the apparent rise; raise it for less. */',
    '    var D = { persp: 640, z: -130, lift: 8, squash: 0.34, blur: 9, floor: 10 };',
    '    /* Clip goes on the stationary wrapper; on #graph it would travel along. */',
    '    var n = graph.getRootNode().host, guard = 0, edge = null;',
    '    while (n && guard++ < 6 && edge === null) {',
    '      var sib = n.nextElementSibling;',
    '      if (sib) { var sr = sib.getBoundingClientRect(); if (sr.height) edge = sr.top; }',
    '      n = n.parentElement || (n.getRootNode() && n.getRootNode().host);',
    '    }',
    '    if (edge !== null) {',
    '      var gap = Math.round(edge - wrap.getBoundingClientRect().bottom);',
    '      if (gap > -40 && gap < 80) D.floor = gap;',
    '    }',
    '    var fy = D.floor < 0 ? "calc(100% - " + Math.abs(D.floor) + "px)"',
    '                         : "calc(100% + " + D.floor + "px)";',
    '    wrap.style.clipPath =',
    '      "polygon(-100% -200%, 200% -200%, 200% " + fy + ", -100% " + fy + ")";',
    '    graph.style.transformOrigin = "50% 90%";',
    '    var from = "perspective(" + D.persp + "px) translateZ(" + D.z + "px)"',
    '             + " translateY(" + D.lift + "px) scaleY(" + D.squash + ")";',
    '    var to = "perspective(" + D.persp + "px) translateZ(0px)"',
