    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: segmentTrackStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '2px 0' }],
      grid: [
        { 'grid-template-areas': '"close p25 p50 p75 open"' },
        { 'grid-template-columns': 'repeat(5, 1fr)' },
        { gap: '6px' },
      ],
      custom_fields: {
        close: [{ 'justify-self': 'stretch' }],
        p25:   [{ 'justify-self': 'stretch' }],
        p50:   [{ 'justify-self': 'stretch' }],
        p75:   [{ 'justify-self': 'stretch' }],
        open:  [{ 'justify-self': 'stretch' }],
      },
    },
    custom_fields: {
      close: { card: makeEdgePill('Close', 'cover.close_cover', 'allFullyClosed') },
      p25:   { card: makePresetPill('25%', 25) },
      p50:   { card: makePresetPill('50%', 50) },
      p75:   { card: makePresetPill('75%', 75) },
      open:  { card: makeEdgePill('Open',  'cover.open_cover',  'allFullyOpen') },
    },
  };

  const controlsCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '16px 28px 0 28px' },
      ],
      grid: [{ 'grid-template-areas': '"a"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { a: [{ 'justify-self': 'stretch' }] },
    },
    custom_fields: {
      a: { card: actionRow },
    },
  };

  /* Cover tiles */
  const makeIconBtn = (coverId, icon, service, activeFn) => {
    const _cid = JSON.stringify(coverId);
    return {
      type: 'custom:button-card',
      entity: coverId,
      icon: icon,
      tap_action: { action: 'call-service', service: service, service_data: { entity_id: coverId } },
      haptic: 'medium',
      show_icon: true, show_name: false, show_label: false, show_state: false,
      card_mod: { style: iconBtnStyle },
      styles: {
        card: [
          { background: `[[[
            const coverId = ${_cid};
            const s = states[coverId]?.state || 'unavailable';
            ${activeFn}
          ]]]` },
          { 'border-radius': '999px' }, { padding: '10px' }, { 'box-shadow': 'none' },
        ],
        grid: [{ display: 'flex' }, { 'align-items': 'center' }, { 'justify-content': 'center' }, { width: '100%' }, { height: '100%' }],
        icon: [{ color: '#ffffff' }, { width: '18px' }, { height: '18px' }, { display: 'flex' }, { 'align-items': 'center' }, { 'justify-content': 'center' }],
      },
    };
  };

  /* Curtain SVGs */
  const CURTAIN_OPEN_URI = 'data:image/svg+xml;base64,';
  const CURTAIN_CLOSED_URI = 'data:image/svg+xml;base64,';

  /* Palette matches hemma_popup_light's makeLightCard, teal instead of yellow. */
  const _cc = {
    onBg:    'rgba(255,255,255,0.94)',
    onName:  'rgba(0,0,0,0.85)',
    onLabel: 'rgba(0,0,0,0.50)',
    offBg:   'rgba(255,255,255,0.11)',
    offName: 'rgba(255,255,255,0.90)',
    offLabel:'rgba(255,255,255,0.50)',
  };

  const makeCoverCard = (coverId) => {
    const _cid = JSON.stringify(coverId);
    return {
      type: 'custom:button-card',
      entity: coverId,
      show_icon: false,
      show_entity_picture: true,
      entity_picture: window.hemmaIconUrl('curtain-open'),
      tap_action: { action: 'more-info' },
      hold_action: { action: 'more-info' },
      double_tap_action: { action: 'none' },
      icon_tap_action: { action: 'toggle' },
      show_name: true,
      show_state: false,
      show_label: true,
      label: `[[[
        const e = states[${_cid}];
        const s = e?.state || 'unknown';
        const lbl = s.charAt(0).toUpperCase() + s.slice(1);
        const pos = e?.attributes?.current_position;
        return (pos != null) ? lbl + ' · ' + Math.round(Number(pos)) + '%' : lbl;
      ]]]`,
      extra_styles: ':host{--hemma-card-hover-filter:brightness(1.10);width:100%!important;max-width:none!important;display:block!important;box-sizing:border-box!important;--button-card-ripple-color:transparent!important;--button-card-ripple-hover-color:transparent!important;--ha-ripple-color:transparent!important;--ha-ripple-hover-color:transparent!important;}ha-card{transition:background 0.45s ease,transform var(--hemma-popup-tile-hover-duration,0.2s) ease,filter var(--hemma-popup-tile-hover-duration,0.2s) ease!important;transform:scale(1)!important;}ha-card:hover{transform:scale(var(--hemma-popup-tile-hover-scale,1.01))!important;}ha-card:active{transform:scale(1)!important;}@media (hover:hover){ha-card:hover{filter:var(--hemma-card-hover-filter,brightness(1.06))!important;}ha-card:hover::after{background:var(--lc-hover-tint,rgba(255,255,255,0.06))!important;}}ha-card::before{display:none!important;}ha-card::after{content:""!important;position:absolute!important;inset:0!important;border-radius:inherit!important;background:transparent!important;transition:background var(--hemma-popup-tile-hover-duration,0.2s) ease!important;pointer-events:none!important;}ha-ripple{display:none!important;}div#img-cell{position:relative!important;overflow:hidden!important;transition:transform var(--hemma-popup-tile-hover-duration,0.2s) ease!important;}div#img-cell::before{display:none!important;}div#img-cell::after{content:""!important;display:block!important;position:absolute!important;inset:0!important;margin:auto!important;width:60%!important;height:60%!important;background-color:var(--cc-clr,#ffffff)!important;-webkit-mask-image:var(--cc-mask)!important;-webkit-mask-repeat:no-repeat!important;-webkit-mask-position:center!important;-webkit-mask-size:contain!important;mask-image:var(--cc-mask)!important;mask-repeat:no-repeat!important;mask-position:center!important;mask-size:contain!important;opacity:var(--cc-io,0.9)!important;pointer-events:none!important;transform:translateZ(0)!important;will-change:transform!important;}div#img-cell:hover,div#img-cell:active{transform:scale(1.03)!important;}#img-cell img{opacity:0!important;}',
      styles: {
        card: [
          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onBg}":"${_cc.offBg}";]]]` },
          { '--cc-nc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onName}":"${_cc.offName}";]]]` },
          { '--cc-lc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onLabel}":"${_cc.offLabel}";]]]` },
          { '--cc-io': `[[[ return "1";]]]` },
          { '--cc-clr': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"#ffffff":"var(--hemma-color-teal, #00c3d0)";]]]` },
          { '--cc-mask': `[[[
              const s = (states[${_cid}]?.state||'').toLowerCase();
              const open = ['open','opening'].includes(s);
              return "url('" + (open ? ${JSON.stringify(CURTAIN_OPEN_URI)} : ${JSON.stringify(CURTAIN_CLOSED_URI)}) + "')";
            ]]]` },
          { '--hemma-card-hover-filter': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"none":"brightness(1.10)";]]]` },
          { '--lc-hover-tint': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"transparent":"rgba(255,255,255,0.06)";]]]` },
          { border: 'none' },
          { 'box-shadow': 'none' },
          { 'border-radius': '26px' },
          { cursor: 'pointer' },
          { padding: '12px 12px' },
          { width: '100%' },
        ],
        grid: [
          { 'grid-template-areas': '"i n" "i l"' },
          { 'grid-template-columns': 'auto 1fr' },
          { 'grid-template-rows': 'auto auto' },
          { 'column-gap': '10px' },
          { 'row-gap': '1px' },
          { 'align-items': 'start' },
        ],
        img_cell: [
          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"var(--hemma-color-teal, #00c3d0)":"rgba(255,255,255,0.10)";]]]` },
          { 'border-radius': '50%' },
          { width: '38px' },
          { height: '38px' },
          { 'min-width': '38px' },
          { display: 'flex' },
          { 'align-items': 'center' },
          { 'justify-content': 'center' },
          { 'align-self': 'center' },
        ],
        entity_picture: [
          { width: '100%' },
          { height: '100%' },
          { 'object-fit': 'contain' },
        ],
        name: [
          { 'font-size': '14px' },
          { 'font-weight': '500' },
          { color: 'var(--cc-nc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'end' },
          { 'line-height': '1.2' },
          { overflow: 'hidden' },
          { 'text-overflow': 'ellipsis' },
          { 'white-space': 'nowrap' },
        ],
        label: [
          { 'font-size': '12px' },
          { color: 'var(--cc-lc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'start' },
          { 'line-height': '1.2' },
        ],
      },
    };
  };

  /* Dynamic grid */
  const colCount = coverIds.length > 1 ? 2 : 1;
  let tileAreas;
  if (colCount === 1) {
    tileAreas = coverIds.map((_, i) => '"t' + i + '"').join(' ');
  } else {
    const rows = [];
    for (let i = 0; i < coverIds.length; i += 2) {
      if (i + 1 < coverIds.length) {
        rows.push('"t' + i + ' t' + (i + 1) + '"');
      } else {
        rows.push('"t' + i + ' t' + i + '"');
      }
    }
    tileAreas = rows.join(' ');
  }
  const tileColDef = colCount === 1 ? '1fr' : '1fr 1fr';

  const tileCF = {}, tileFS = {};
  coverIds.forEach((id, i) => {
    tileCF['t' + i] = { card: makeCoverCard(id) };
    tileFS['t' + i] = [{ 'justify-self': 'stretch' }, { 'text-align': 'left' }];
  });

  const tilesCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '16px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': tileAreas },
        { 'grid-template-columns': tileColDef },
        { gap: '10px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFS,
    },
    custom_fields: tileCF,
  };

  const stackCards = [headerCard, controlsCard, tilesCard];
  if (hitzeschutzCard) stackCards.splice(1, 0, hitzeschutzCard);
  return { type: 'vertical-stack', cards: stackCards };
]]]

