data.content:
[[[
  const powerId     = variables.entity_power || entity?.entity_id;
  const todayId     = variables.entity_usage_today;
  const monthId     = variables.entity_usage_month;
  const costTodayId = variables.entity_cost_today;
  const costMonthId = variables.entity_cost_month;
  const roomName    = variables.room_name || 'Energy';

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id] && states[id].state;
    if (!s || s === 'unknown' || s === 'unavailable') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const costCurrency = (costTodayId && states[costTodayId]?.attributes?.unit_of_measurement)
    || (costMonthId  && states[costMonthId]?.attributes?.unit_of_measurement)
    || '';

  const power = safeNum(powerId);

  window._hc = window._hc || {};
  const _ck = 'hemma_energy_' + (powerId || 'x');
  const _memoSub = (subKey, dep, factory) => {
    const key = _ck + '_' + subKey;
    if (window._hc[key]?.h === dep) return window._hc[key].r;
    const r = factory();
    window._hc[key] = { h: dep, r };
    return r;
  };

  const tNormal  = Number(variables.normal_threshold  ?? 200);
  const tHeavy   = Number(variables.heavy_threshold   ?? 1000);
  const tExtreme = Number(variables.extreme_threshold ?? 3000);

  // Usage tier — drives the graph line and the memo keys below
  const statusLabel = power >= tExtreme ? 'Extreme' : power >= tHeavy ? 'Heavy' : power >= tNormal ? 'Normal' : 'Idle';
  // apexcharts can't resolve CSS vars, so these mirror the Apple palette literally
  const graphColor  = power >= tExtreme ? '#FF4245' : power >= tHeavy ? '#FF9230' : power >= tNormal ? '#FFD600' : '#30D158';

  // Safe JSON literals for inner templates
  const _pid  = JSON.stringify(powerId     || '');
  const _tid  = JSON.stringify(todayId     || '');
  const _mid  = JSON.stringify(monthId     || '');
  const _ctid = JSON.stringify(costTodayId || '');
  const _cmid = JSON.stringify(costMonthId || '');
  const _cur  = JSON.stringify(costCurrency);

  // Shared helper snippets
  const _safe = "const safeNum=(id)=>{if(!id)return null;const s=states[id]&&states[id].state;if(!s||s==='unknown'||s==='unavailable')return null;const n=parseFloat(s);return isNaN(n)?null:n;};";
  const _fmt  = "const fmtPower=(v)=>v==null?'—':String(Math.round(v));const fmtEnergy=(v)=>{if(v==null)return'—';if(v<1)return v.toFixed(2);if(v<10)return v.toFixed(1);return Math.round(v).toString();};";

  // Power → color
  const _powerScore = `
    const tNormal = ${tNormal}, tHeavy = ${tHeavy}, tExtreme = ${tExtreme};
    const power = safeNum(powerId);
    let color = 'var(--hemma-popup-green-color, #30D158)', label = 'Idle';
    if (power >= tExtreme)     { color = 'var(--hemma-popup-red-color, #ff4245)';    label = 'Extreme'; }
    else if (power >= tHeavy)  { color = 'var(--hemma-popup-orange-color, #ff9230)'; label = 'Heavy'; }
    else if (power >= tNormal) { color = 'var(--hemma-popup-yellow-color, #ffd600)'; label = 'Normal'; }
  `;

  // Tooltip time format
  const _tf = hass?.locale?.time_format;
  const _use12hr = _tf === '12' || (_tf !== '24' && new Intl.DateTimeFormat(hass?.locale?.language || 'en', { hour: 'numeric' }).resolvedOptions().hour12);
  const tooltipTimeFormat = _use12hr ? 'h:mm tt' : 'HH:mm';

  /* Styles */

  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; pointer-events: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    '#container { overflow: visible !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }',
    'ha-card { background: var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--hemma-popup-tile-hover-duration, 0.2s) ease, transform var(--hemma-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    'ha-card:hover { background: var(--hemma-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--hemma-popup-tile-hover-scale, 1.01)) !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const tapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; pointer-events: auto !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; }',
    'ha-card #container { transition: opacity 0.18s ease, filter 0.18s ease !important; }',
    'ha-card:hover #container { filter: brightness(1.12) saturate(1.08) drop-shadow(0 0 10px rgba(255,255,255,0.05)); }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  /* card_mod lands too late to hide the empty chart shell, so the
     entrance animation runs from apex_config instead. EVAL: is
     apexcharts-card's hook for a function in a serialised config. */
  const chartEnter = 'EVAL:' + [
    'function (ctx) {',
    '  try {',
    '    var graph = ctx && ctx.el;',
    '    if (!graph || (ctx.w && ctx.w.globals && ctx.w.globals.noData)) return;',
    '    var wrap = graph.closest("#graph-wrapper") || graph.parentElement;',
    '    if (!wrap || !graph.animate || wrap.dataset.hemmaChartEntered) return;',
    '    wrap.dataset.hemmaChartEntered = "1";',
    '    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {',
    '      graph.animate([{ opacity: 0 }, { opacity: 1 }],',
    '        { duration: 200, easing: "ease-out", fill: "backwards" });',
    '      return;',
    '    }',
    '    /* squash, not lift, drives the apparent rise; raise it for less. */',
    '    var D = { persp: 640, z: -130, lift: 8, squash: 0.34, blur: 9, floor: 10 };',
    '    /* Clip goes on the stationary wrapper; on #graph it would travel along. */',
    '    var n = graph.getRootNode().host, guard = 0, edge = null;',
    '    while (n && guard++ < 6 && edge === null) {',
    '      var sib = n.nextElementSibling;',
    '      if (sib) { var sr = sib.getBoundingClientRect(); if (sr.height) edge = sr.top; }',
    '      n = n.parentElement || (n.getRootNode() && n.getRootNode().host);',
    '    }',
    '    if (edge !== null) {',
    '      var gap = Math.round(edge - wrap.getBoundingClientRect().bottom);',
    '      if (gap > -40 && gap < 80) D.floor = gap;',
    '    }',
    '    var fy = D.floor < 0 ? "calc(100% - " + Math.abs(D.floor) + "px)"',
    '                         : "calc(100% + " + D.floor + "px)";',
    '    wrap.style.clipPath =',
    '      "polygon(-100% -200%, 200% -200%, 200% " + fy + ", -100% " + fy + ")";',
    '    graph.style.transformOrigin = "50% 90%";',
    '    var from = "perspective(" + D.persp + "px) translateZ(" + D.z + "px)"',
    '             + " translateY(" + D.lift + "px) scaleY(" + D.squash + ")";',
    '    var to = "perspective(" + D.persp + "px) translateZ(0px)"',
    '           + " translateY(0px) scaleY(1)";',
    '    graph.animate([{ opacity: 0 }, { opacity: 1 }],',
    '      { duration: 600, easing: "ease-out", fill: "backwards" });',
    '    graph.animate([{ filter: "blur(" + D.blur + "px)" }, { filter: "blur(0px)" }],',
    '      { duration: 600, easing: "ease-out", fill: "backwards" });',
    '    var rise = graph.animate([{ transform: from }, { transform: to }],',
    '      { duration: 700, easing: "cubic-bezier(0.22, 1, 0.36, 1)", fill: "backwards" });',
    '    /* Clear the clip or it can trap a tooltip later. */',
    '    var unclip = function () { wrap.style.clipPath = ""; };',
    '    if (rise.finished) rise.finished.then(unclip).catch(unclip);',
    '    else rise.onfinish = unclip;',
    '  } catch (e) {}',
    '}',
  ].join('\n');

  const graphStyle = `
    :host {
      position: relative !important;
      z-index: 1 !important;
      --ha-card-box-shadow: none !important;
      --button-card-box-shadow: none !important;
      --button-card-box-shadow-hover: none !important;
    }

    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;
      box-shadow: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
      overflow: visible !important;
      --primary-color: transparent !important;
    }

    ha-card:hover {
      box-shadow: none !important;
      border-color: transparent !important;
    }

    #spinner-wrapper { display: none !important; }

    #graph {
      margin: 0 !important;
      padding: 8px 0 !important;
      overflow: visible !important;
      background: transparent !important;
    }

    .apexcharts-canvas {
      overflow: visible !important;
      background: transparent !important;
    }

    .apexcharts-canvas > svg {
      -webkit-mask-image:
        linear-gradient(to right, rgba(0,0,0,0) 0%, rgba(0,0,0,0) 4%, rgba(0,0,0,0.4) 12%, black 22%, black 78%, rgba(0,0,0,0.4) 88%, rgba(0,0,0,0) 96%, rgba(0,0,0,0) 100%),
        linear-gradient(to bottom, transparent 0%, black 10%, black 82%, transparent 100%);
      mask-image:
        linear-gradient(to right, rgba(0,0,0,0) 0%, rgba(0,0,0,0) 4%, rgba(0,0,0,0.4) 12%, black 22%, black 78%, rgba(0,0,0,0.4) 88%, rgba(0,0,0,0) 96%, rgba(0,0,0,0) 100%),
        linear-gradient(to bottom, transparent 0%, black 10%, black 82%, transparent 100%);
      -webkit-mask-composite: destination-in;
      mask-composite: intersect;
      -webkit-mask-repeat: no-repeat;
      mask-repeat: no-repeat;
      -webkit-mask-size: 100% 100%;
      mask-size: 100% 100%;
    }

    .apexcharts-tooltip {
      transition: opacity 0.12s ease !important;
      display: inline-block !important;
      width: max-content !important;
      max-width: 160px !important;
      min-width: 80px !important;
      white-space: nowrap !important;
      --hemma-chart-tooltip-fill: rgba(22,22,24,0.80);
      background:
        linear-gradient(var(--hemma-glass-background, rgba(255,255,255,0.10)),
                        var(--hemma-glass-background, rgba(255,255,255,0.10))),
        var(--hemma-chart-tooltip-fill) !important;
      border: none !important;
      border-radius: 14px !important;
      box-shadow: var(--hemma-glass-rim,
        inset 0 1px .5px -0.5px rgba(255,255,255,0.55),
        inset 0 -1px .5px -0.5px rgba(255,255,255,0.48),
        inset 0 3px 6px -3px rgba(255,255,255,0.20),
        inset 0 -3px 6px -3px rgba(255,255,255,0.12),
        2px 0 3px -2px rgba(0,0,0,0.45),
        -2px 0 3px -2px rgba(0,0,0,0.45),
        0 2px 8px rgba(0,0,0,0.18)) !important;
      overflow: hidden !important;
    }

    .apexcharts-tooltip-title,
    .apexcharts-tooltip-series-group {
      width: auto !important;
      max-width: 120px !important;
    }

    .apexcharts-tooltip-title {
      background: transparent !important;
      border-bottom: none !important;
      font-size: 10px !important;
      color: rgba(255,255,255,0.58) !important;
      font-weight: 600 !important;
      padding: 9px 12px 2px !important;
      margin: 0 !important;
      letter-spacing: 0.07em !important;
      text-transform: uppercase !important;
    }

    .apexcharts-tooltip-series-group {
      background: transparent !important;
      padding: 0 12px 9px !important;
      align-items: center !important;
    }

    .apexcharts-tooltip-series-group.apexcharts-active {
      background: transparent !important;
    }

    .apexcharts-tooltip-marker { display: none !important; }
    .apexcharts-tooltip-text-y-label { display: none !important; }

    .apexcharts-tooltip-text-y-value {
      color: rgba(255,255,255,0.98) !important;
      font-weight: 700 !important;
      font-size: 16px !important;
      margin-left: 0 !important;
    }

    .apexcharts-xcrosshairs {
      stroke: rgba(255,255,255,0.14) !important;
      stroke-dasharray: 3 3 !important;
      stroke-width: 1 !important;
    }

    .apexcharts-xaxistooltip { display: none !important; }
    .apexcharts-ycrosshairs { display: none !important; }
  `;

  /* Power Gauge */
  const gaugeCard = _memoSub('gauge', String(powerId), () => ({
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'more-info' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tapStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'end' }] },
    },
    custom_fields: {
      c: `[[[
        const powerId = ${_pid};
        ${_safe}
        ${_fmt}
        ${_powerScore}
        const circ = 2 * Math.PI * 42;
        const dashOffset = circ - Math.min((power || 0) / 5000, 1) * circ;
        return '<div style="position:relative;width:120px;height:120px;">'
          + '<svg viewBox="0 0 100 100" style="width:100%;height:100%;transform:rotate(-90deg);">'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="var(--hemma-popup-progress-track, rgba(255,255,255,0.08))" stroke-width="7"/>'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="' + color + '" stroke-width="7" stroke-linecap="round" stroke-dasharray="' + circ.toFixed(2) + '" stroke-dashoffset="' + dashOffset.toFixed(2) + '"/>'
          + '</svg>'
          + '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;">'
            + '<div style="font-size:11px;color:var(--hemma-popup-tiles-text-muted);letter-spacing:.08em;font-weight:500;">WATT</div>'
            + '<div style="color:' + color + ';font-size:28px;font-weight:600;line-height:1;">' + fmtPower(power) + '</div>'
            + '<div style="color:var(--hemma-popup-tiles-text-muted);font-size:14px;margin-top:-4px;">W</div>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  }));

  /* Right Column */
  const rightColCard = _memoSub('rightcol', statusLabel, () => ({
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: wrapperStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [
        { display: 'flex' }, { 'flex-direction': 'column' }, { 'align-items': 'flex-end' }, { gap: '28px' },
      ],
      custom_fields: {
        ring: [{ flex: '0 0 auto' }, { 'margin-top': '66px' }],
      },
    },
    custom_fields: {
      ring: { card: gaugeCard },
    },
  }));

  /* Header Stat Cards */
  const makeHeaderStatCard = (entityId, labelText, costEntityId, side) => ({
    type: 'custom:button-card',
    entity: entityId || powerId,
    tap_action: entityId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: entityId ? tapStyle : noHoverStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }, { 'text-align': 'left' }],
      custom_fields: { c: [{ 'justify-self': 'start' }] },
    },
    custom_fields: {
      c: `[[[
        const entityId     = ${JSON.stringify(entityId || '')};
        const costEntityId = ${JSON.stringify(costEntityId || '')};
        const costCurrency = ${_cur};
        const labelText    = ${JSON.stringify(labelText)};
        const side         = ${JSON.stringify(side)};
        ${_safe}
        ${_fmt}
        const v     = safeNum(entityId);
        const costV = safeNum(costEntityId);
        const costStr = costV != null ? costCurrency + costV.toFixed(2) : '';
        return '<div style="text-align:left;' + (side === 'right' ? 'padding-right:6px;' : side === 'left' ? 'padding-left:6px;' : '') + '">'
          + '<div style="font-size:11px;color:var(--hemma-popup-tiles-text-muted);letter-spacing:.06em;font-weight:500;">' + labelText + '</div>'
          + '<div style="display:flex;align-items:baseline;gap:4px;margin-top:5px;">'
            + '<span style="font-size:22px;">' + fmtEnergy(v) + '</span>'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-muted);">kWh</span>'
          + '</div>'
          + (costStr ? '<div style="font-size:13px;color:var(--hemma-popup-tiles-text-muted);margin-top:5px;">' + costStr + '</div>' : '')
        + '</div>';
      ]]]`,
    },
  });

  /* Stats Wrapper */
  const statsWrapperCard = {
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: wrapperStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [
        { display: 'flex' }, { 'flex-direction': 'row' }, { 'align-items': 'flex-start' },
        { 'justify-content': 'flex-start' }, { gap: '0' },
      ],
      custom_fields: {
        today: [{ flex: '0 0 auto' }, { order: '1' }],
        div:   [{ flex: '0 0 auto' }, { 'align-self': 'stretch' }, { order: '2' }],
        month: [{ flex: '0 0 auto' }, { order: '3' }],
      },
    },
    custom_fields: {
      today: { card: makeHeaderStatCard(todayId, 'TODAY', costTodayId, 'right') },
      div:   '<div style="width:2px;height:100%;background:rgba(255,255,255,0.09);margin:0 12px;"></div>',
      month: { card: makeHeaderStatCard(monthId, 'MONTH', costMonthId, 'left') },
    },
  };

  /* Header Card */
  const headerCard = _memoSub('header', statusLabel, () => ({
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '28px 28px 0 28px' },
      ],
      grid: [
        { 'grid-template-areas': '"title right" "stats right"' },
        { 'grid-template-columns': '1fr auto' },
        { 'align-items': 'flex-start' },
        { 'row-gap': '16px' },
      ],
      custom_fields: {
        title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        right: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
        stats: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
      },
    },
    custom_fields: {
      title: '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary);text-align:left;">'
        + `<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;">${roomName}</div>`
        + '<div style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary);margin-top:2px;">Power · Consumption</div>'
        + '<div style="font-size:22px;font-weight:400;letter-spacing:-.5px;margin-top:20px;margin-bottom:16px;">Energy Usage</div>'
        + '</div>',
      right: { card: rightColCard },
      stats: { card: statsWrapperCard },
    },
  }));

  /* Graph Card */
  const graphCard = {
    type: 'custom:apexcharts-card',
    graph_span: '4h',
    header: { show: false },
    yaxis: [{ min: 0, max: '~1000', show: false }],
    series: [{
      entity: powerId,
      color: graphColor,
      type: 'area',
      curve: 'monotoneCubic',
      stroke_width: 3,
      float_precision: 0,
      extend_to: 'now',
      group_by: { func: 'avg', duration: '15min', fill: 'last' },
    }],
    apex_config: {
      noData: { text: '' },
      chart: {
        events: { mounted: chartEnter, updated: chartEnter },
        height: 88,
        background: 'transparent',
        toolbar: { show: false },
        zoom: { enabled: false },
        animations: {
          enabled: true,
          speed: 300,
          animateGradually: { enabled: false },
          dynamicAnimation: { speed: 300 },
        },
      },
      theme: { mode: 'dark' },
      stroke: { curve: 'monotoneCubic', width: 3, lineCap: 'round' },
      grid: { show: false, padding: { left: 0, right: 0, top: -8, bottom: -12 } },
      xaxis: { labels: { show: false }, axisBorder: { show: false }, axisTicks: { show: false } },
      dataLabels: { enabled: false },
      legend: { show: false },
      tooltip: {
        enabled: true,
        shared: true,
        intersect: false,
        theme: 'dark',
        x: { show: true, format: tooltipTimeFormat },
        fixed: { enabled: false },
      },
      fill: {
        type: 'gradient',
        gradient: {
          type: 'vertical',
          shadeIntensity: 0,
          opacityFrom: 0.65,
          opacityTo: 0.0,
          stops: [0, 100],
        },
      },
      markers: { size: 0, colors: ['#ffffff'], strokeColors: 'rgba(255,255,255,0.4)', strokeWidth: 0, hover: { size: 5 } },
    },
    card_mod: { style: graphStyle },
  };

  /* Stat Tiles */

  // Tile card shared styles (same for all three)
  const tileCardStyles = {
    card: [
      { background: 'rgba(255,255,255,0.045)' }, { border: 'none' }, { borderRadius: '24px' },
      { boxShadow: 'none' }, { backdropFilter: 'none' }, { WebkitBackdropFilter: 'none' },
      { padding: '18px 18px 16px 18px' },
    ],
    grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
    custom_fields: { c: [{ 'justify-self': 'stretch' }] },
  };

  const currentStat = {
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'more-info' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tileTapStyle },
    styles: tileCardStyles,
    custom_fields: {
      c: `[[[
        const powerId = ${_pid};
        ${_safe}
        ${_fmt}
        ${_powerScore}
        const currentPct =
          power == null ? 0 :
          power >= tExtreme ? Math.min(85 + ((power - tExtreme) / (tExtreme - tHeavy)) * 15, 100) :
          power >= tHeavy   ? 50 + ((power - tHeavy)  / (tExtreme - tHeavy)) * 35 :
          power >= tNormal  ? 25 + ((power - tNormal) / (tHeavy - tNormal))  * 25 :
          (power / tNormal) * 25;
        const pct = Math.max(0, Math.min(100, currentPct));
        const gradient = color;

        return '<div style="margin-top:1px;min-width:0;overflow:hidden;">'
          + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px;">'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-primary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.01em;">Now</span>'
            + '<span style="font-size:13px;color:' + color + ';white-space:nowrap;font-weight:600;letter-spacing:.01em;flex-shrink:0;">' + label + '</span>'
          + '</div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;">'
            + '<span style="font-size:20px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);line-height:1;white-space:nowrap;">' + fmtPower(power) + '</span>'
            + '<span style="font-size:12px;color:var(--hemma-popup-tiles-text-muted);white-space:nowrap;">W</span>'
          + '</div>'
          + '<div style="position:relative;height:8px;width:100%;background:var(--hemma-popup-progress-track, rgba(255,255,255,0.09));border-radius:999px;overflow:hidden;margin-top:10px;">'
            + '<div style="position:absolute;inset:0 auto 0 0;width:' + pct.toFixed(1) + '%;border-radius:999px;background:' + gradient + ';transition:width .35s ease;"></div>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  // "Today" tile
  const todayStat = {
    type: 'custom:button-card',
    entity: todayId || powerId,
    tap_action: todayId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: todayId ? tileTapStyle : noHoverStyle },
    styles: tileCardStyles,
    custom_fields: {
      c: `[[[
        const todayId     = ${_tid};
        const costTodayId = ${_ctid};
        const costCurrency = ${_cur};
        ${_safe}
        ${_fmt}
        const v     = safeNum(todayId);
        const costV = safeNum(costTodayId);
        const costStr = costV != null ? costCurrency + costV.toFixed(2) : '';
        const pct = Math.max(0, Math.min(100, (v || 0) / 50 * 100));
        const color = pct >= 85 ? 'var(--hemma-popup-red-color, #ff4245)' : pct >= 45 ? 'var(--hemma-popup-orange-color, #ff9230)' : 'var(--hemma-popup-green-color, #30D158)';
        const gradient = color;
        return '<div style="margin-top:1px;min-width:0;overflow:hidden;">'
          + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px;">'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-primary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.01em;">Today</span>'
            + (costStr ? '<span style="font-size:13px;color:' + color + ';white-space:nowrap;font-weight:600;letter-spacing:.01em;flex-shrink:0;">' + costStr + '</span>' : '')
          + '</div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;">'
            + '<span style="font-size:20px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);line-height:1;white-space:nowrap;">' + fmtEnergy(v) + '</span>'
            + '<span style="font-size:12px;color:var(--hemma-popup-tiles-text-muted);white-space:nowrap;">kWh</span>'
          + '</div>'
          + '<div style="position:relative;height:8px;width:100%;background:var(--hemma-popup-progress-track, rgba(255,255,255,0.09));border-radius:999px;overflow:hidden;margin-top:10px;">'
            + '<div style="position:absolute;inset:0 auto 0 0;width:' + pct.toFixed(1) + '%;border-radius:999px;background:' + gradient + ';transition:width .35s ease;"></div>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  // "Month" tile
  const monthStat = {
    type: 'custom:button-card',
    entity: monthId || powerId,
    tap_action: monthId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: monthId ? tileTapStyle : noHoverStyle },
    styles: tileCardStyles,
    custom_fields: {
      c: `[[[
        const monthId     = ${_mid};
        const costMonthId = ${_cmid};
        const costCurrency = ${_cur};
        ${_safe}
        ${_fmt}
        const v     = safeNum(monthId);
        const costV = safeNum(costMonthId);
        const costStr = costV != null ? costCurrency + costV.toFixed(2) : '';
        const pct = Math.max(0, Math.min(100, (v || 0) / 1500 * 100));
        const color = pct >= 85 ? 'var(--hemma-popup-red-color, #ff4245)' : pct >= 45 ? 'var(--hemma-popup-orange-color, #ff9230)' : 'var(--hemma-popup-green-color, #30D158)';
        const gradient = color;
        return '<div style="margin-top:1px;min-width:0;overflow:hidden;">'
          + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px;">'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-primary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.01em;">Month</span>'
            + (costStr ? '<span style="font-size:13px;color:' + color + ';white-space:nowrap;font-weight:600;letter-spacing:.01em;flex-shrink:0;">' + costStr + '</span>' : '')
          + '</div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;">'
            + '<span style="font-size:20px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);line-height:1;white-space:nowrap;">' + fmtEnergy(v) + '</span>'
            + '<span style="font-size:12px;color:var(--hemma-popup-tiles-text-muted);white-space:nowrap;">kWh</span>'
          + '</div>'
          + '<div style="position:relative;height:8px;width:100%;background:var(--hemma-popup-progress-track, rgba(255,255,255,0.09));border-radius:999px;overflow:hidden;margin-top:10px;">'
            + '<div style="position:absolute;inset:0 auto 0 0;width:' + pct.toFixed(1) + '%;border-radius:999px;background:' + gradient + ';transition:width .35s ease;"></div>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Stats Grid Card */
  const isMobile = typeof window !== 'undefined' && window.innerWidth <= 600;

  const statsCard = {
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '4px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': isMobile ? '"stat1 stat2" "stat3 stat3"' : '"stat1 stat2 stat3"' },
        { 'grid-template-columns': isMobile ? '1fr 1fr' : 'repeat(3, 1fr)' },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: {
        stat1: [{ 'justify-self': 'stretch' }],
        stat2: [{ 'justify-self': 'stretch' }],
        stat3: [{ 'justify-self': 'stretch' }],
      },
    },
    custom_fields: {
      stat1: { card: currentStat },
      stat2: { card: todayStat },
      stat3: { card: monthStat },
    },
  };

  return {
    type: 'vertical-stack',
    cards: [headerCard, graphCard, statsCard],
  };
]]]

data.tag:
[[[
  const id = variables.entity_power || entity?.entity_id || 'home';
  return 'hemma_energy_' + String(id).replace(/\./g, '_');
]]]

popup_styles.styles:
ha-adaptive-dialog, ha-dialog, wa-drawer {
  --dialog-surface-margin-top: 90px;
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

data.content:
[[[
  const powerId     = variables.entity_power || entity?.entity_id;
  const todayId     = variables.entity_usage_today;
  const monthId     = variables.entity_usage_month;
  const costTodayId = variables.entity_cost_today;
  const costMonthId = variables.entity_cost_month;
  const roomName    = variables.room_name || 'Energy';

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id] && states[id].state;
    if (!s || s === 'unknown' || s === 'unavailable') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const costCurrency = (costTodayId && states[costTodayId]?.attributes?.unit_of_measurement)
    || (costMonthId  && states[costMonthId]?.attributes?.unit_of_measurement)
    || '';

  const power = safeNum(powerId);

  window._hc = window._hc || {};
  const _ck = 'hemma_energy_' + (powerId || 'x');
  const _memoSub = (subKey, dep, factory) => {
