                const snap = {};
                ${_lightIds}.forEach(id => {
                  const s = h.states[id]; if (!s) return;
                  snap[id] = s.state+'|'+(s.attributes?.brightness??'')+'|'+(s.attributes?.color_temp??'')+'|'+JSON.stringify(s.attributes?.rgb_color??null);
                });
                window._hemmaSceneSnap[_gid] = snap;
              }, 2500);
