            }

            if (_hasScenes && d.hemma_sc_toggle === _gid) {
              const _sg = window._hemmaScGrid?.[_gid];
              const _sl = window._hemmaScLbl?.[_gid];
              if (_sg) {
                const _wasCollapsed = _sg.style.maxHeight === '0px';
                if (_wasCollapsed) {
                  _sg.style.overflow = 'hidden';
                  _sg.style.opacity = '0';
                  _sg.style.transform = 'translateY(-6px)';
                  _sg.style.transition = 'none';
                  _sg.style.maxHeight = '0px';
                  requestAnimationFrame(function(){ requestAnimationFrame(function(){
                    const _nh = _sg.scrollHeight + 'px';
                    _sg.style.transition = 'max-height 0.25s cubic-bezier(0.25,0.46,0.45,0.94),opacity 0.22s ease,transform 0.22s ease';
                    _sg.style.maxHeight = _nh;
