                  if (_sl) { _sl.style.setProperty('--sc-rot', '0deg'); _sl.style.setProperty('--sc-lbl-pb', '12px'); }
                }
                setTimeout(function(){ _applyHeightFix(_getHad()); }, 50);
              }
              return;
