data.content:
[[[
  /* Variables */
  const groupId  = entity?.entity_id || null;
  const lockIds  = Array.isArray(variables.locks) && variables.locks.length > 0
                  ? variables.locks
                  : (groupId ? [groupId] : []);
  const roomName = variables.room_name || 'Access Control';

  const _gid     = JSON.stringify(groupId);
  const _lockIds = JSON.stringify(lockIds);

  const _countSnip = `
    const lockIds = ${_lockIds};
    const lc  = lockIds.filter(id => states[id]?.state === 'locked').length;
    const uc  = lockIds.length - lc;
    const tot = lockIds.length;
    const allLkd  = lc === tot && tot > 0;
    const allUlkd = lc === 0   && tot > 0;
    const badgeColor = allLkd ? 'var(--hemma-popup-green-color,#30D158)' : 'var(--hemma-popup-orange-color,#ff9230)';
  `;

  /* Styles (static) */
  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; overflow: visible !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; overflow: visible !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; overflow: visible !important; }',
    'ha-card { background: var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: default !important; overflow: visible !important; transition: background var(--hemma-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    '@media (hover: hover) { ha-card:hover { background: var(--hemma-popup-tile-background-hover, rgba(255,255,255,0.10)) !important; } }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const lockTileStaticStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; overflow: visible !important; }',
    'ha-card { border: none !important; border-radius: 24px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; overflow: visible !important; }',
    '@media (hover: hover) { ha-card:hover { filter: brightness(1.04) !important; } }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const lockIconBtnStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; overflow: visible !important; display: block !important; }',
    'ha-card { border: none !important; border-radius: 999px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: pointer !important; overflow: visible !important; aspect-ratio: 1 !important; display: flex !important; align-items: center !important; justify-content: center !important; transition: background 0.15s ease, filter 0.15s ease, transform 0.15s ease !important; }',
    'ha-card:hover { filter: brightness(1.25) !important; transform: scale(1.08) !important; }',
    '#container { display: flex !important; align-items: center !important; justify-content: center !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const openBtnStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { border: none !important; border-radius: 999px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: pointer !important; transition: background 0.15s ease, filter 0.15s ease !important; }',
    'ha-card:hover { filter: brightness(1.25) !important; }',
    '#icon { display: flex !important; align-items: center !important; justify-content: center !important; }',
    'ha-icon { --mdc-icon-size: 16px !important; display: flex !important; align-items: center !important; justify-content: center !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  /* Header card */
  const headerCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '28px 28px 0 28px' },
      ],
      grid: [
        { 'grid-template-areas': '"title"' },
        { 'grid-template-columns': '1fr auto' },
        { 'align-items': 'flex-start' },
        { 'row-gap': '16px' },
      ],
      custom_fields: {
        title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        right: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
      },
    },
    custom_fields: {
      title: `[[[
        return '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary,#ffffff);text-align:left;">'
          + '<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;">' + ${JSON.stringify(roomName)} + '</div>'
          + '<div style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary,rgba(255,255,255,0.75));margin-top:2px;">Security · Access Control</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Advice card */
  const adviceCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '20px 28px 18px 28px' },
      ],
      grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { body: [{ 'justify-self': 'stretch' }, { width: '100%' }, { 'text-align': 'left' }] },
    },
    custom_fields: {
      body: `[[[
        ${_countSnip}
        const advice = allLkd  ? (tot === 1 ? 'Door locked' : 'All doors locked')
                     : allUlkd ? (tot === 1 ? 'Door unlocked' : 'All doors unlocked')
                     : uc === 1 ? '1 door unlocked' : uc + ' doors unlocked';
        return '<div style="font-family:var(--primary-font-family,system-ui);">'
          + '<div style="font-size:22px;color:var(--primary-text-color,#ffffff);font-weight:400;letter-spacing:-.5px;">' + advice + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Lock tiles */
  const makeLockTile = (lockId) => {
    const _lid = JSON.stringify(lockId);

    const rawName = states[lockId]?.attributes?.friendly_name || lockId.split('.').pop() || lockId;
    let tileName = rawName;
    if (tileName.includes(')')) tileName = tileName.substring(tileName.lastIndexOf(')') + 1);
    tileName = tileName.replace(/^[-\s]+/, '').replace(/_/g, ' ').trim() || rawName;
    const _name = JSON.stringify(tileName);

    const battId = (variables.battery_entities && variables.battery_entities[lockId]) || null;
    const _battId = JSON.stringify(battId);
    const doorId = (variables.door_sensors && variables.door_sensors[lockId]) || null;
    const _doorId = JSON.stringify(doorId);

    const togglePillCard = {
      type: 'custom:button-card',
      entity: lockId,
      show_icon: false,
      show_name: false,
      show_state: false,
      show_label: false,
      show_entity_picture: false,
      tap_action: `[[[
        const lockId = ${_lid};
        const s = states[lockId]?.state;
        if (s === 'locked') return { action: 'call-service', service: 'lock.unlock', service_data: { entity_id: lockId } };
        if (s === 'unlocked') return { action: 'call-service', service: 'lock.lock', service_data: { entity_id: lockId } };
        return { action: 'none' };
      ]]]`,
      haptic: 'medium',
      extra_styles: `
        @keyframes hemma-thumb-on-d{from{transform:translateX(0)}to{transform:translateX(20px)}}
        @keyframes hemma-thumb-off-d{from{transform:translateX(20px)}to{transform:translateX(0)}}
        @keyframes hemma-thumb-on-m{from{transform:translateX(0)}to{transform:translateX(20px)}}
        @keyframes hemma-thumb-off-m{from{transform:translateX(20px)}to{transform:translateX(0)}}
        :host { display: block !important; overflow: visible !important; }
        ha-card { background: transparent !important; border: none !important; box-shadow: none !important; backdrop-filter: none !important; padding: 0 !important; overflow: visible !important; cursor: pointer !important; }
        #container { padding: 0 !important; overflow: visible !important; }
        ha-ripple { display: none !important; }
        svg .lk-hover-track { opacity: 0; transition: opacity 0.2s ease; pointer-events: none; }
        svg .lk-overlay { fill: transparent; transition: fill 0.2s ease; pointer-events: none; }
        @media (hover: hover) {
          :host(:hover) svg .lk-hover-track { opacity: 0.65; }
          :host(:hover) svg .lk-overlay { fill: rgba(255,255,255,0.06); }
        }
      `,
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }, { overflow: 'visible' }],
        grid: [{ 'grid-template-areas': '"svg"' }, { 'grid-template-columns': 'auto' }, { 'align-items': 'center' }, { 'justify-items': 'center' }],
        custom_fields: { svg: [{ 'line-height': '0' }] },
      },
      custom_fields: {
        svg: `[[[
