data.content:
[[[
  const moviesData = states['sensor.recently_added_movies']?.attributes?.data;
  const tvData     = states['sensor.recently_added_tv']?.attributes?.data;

  const rawM = Array.isArray(moviesData) ? moviesData.slice(1).filter(i => i && i.title) : [];
  const rawT = Array.isArray(tvData)     ? tvData.slice(1).filter(i => i && i.title)     : [];
  const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
  const items = [
    ...rawM.map(i => Object.assign({}, i, {_isTV: false})),
    ...rawT.map(i => Object.assign({}, i, {_isTV: true})),
  ].filter(i => i.airdate && new Date(i.airdate).getTime() >= cutoff)
   .sort((a, b) => new Date(b.airdate || 0) - new Date(a.airdate || 0));
  const N = items.length;

  /* helpers */
  const esc = s => String(s ?? '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');

  const resolveUrl = raw => {
    if (!raw) return '';
    const s = String(raw);
    return s.startsWith('/') ? location.origin + s : s;
  };

  const ago = iso => {
    if (!iso) return '';
    const ms = Date.now() - new Date(iso).getTime();
    const h  = ms / 3600000;
    const d  = ms / 86400000;
    if (h < 1)  return 'just now';
    if (h < 24) return Math.floor(h) + 'h ago';
    if (d < 7)  return Math.floor(d) + 'd ago';
    return Math.floor(d / 7) + 'w ago';
  };

  /* empty state */
  if (N === 0) {
    const noHoverStyle = [
      ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
      'ha-card { background: transparent !important; border: none !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }',
      'ha-card:hover { box-shadow: none !important; border-color: transparent !important; }',
      'ha-ripple { display: none !important; }',
    ].join('\n');

    const emptyBadge = {
      type: 'custom:button-card',
      name: 'Up to date',
      tap_action: { action: 'none' },
      show_icon: false, show_name: true, show_label: false, show_state: false,
      card_mod: {
        style: [
          ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
          'ha-card { border: none !important; border-radius: 999px !important; padding: 11px 16px !important; backdrop-filter: var(--hemma-glass-pill-backdrop, none) !important; -webkit-backdrop-filter: var(--hemma-glass-pill-backdrop, none) !important; box-shadow: inset 0 1px 0.5px -0.5px var(--pill-glow-top-tight), inset 0 -1px 0.5px -0.5px var(--pill-glow-bottom-tight), inset 0 3px 6px -3px var(--pill-glow-top-soft), inset 0 -3px 6px -3px var(--pill-glow-bottom-soft), inset 0 0 0 999px rgba(255,255,255,0) !important; cursor: default !important; position: relative !important; overflow: visible !important; transition: box-shadow 0.2s ease !important; --pill-glow-top-tight: color-mix(in srgb, color-mix(in srgb, var(--pill-accent,#ffffff) var(--hemma-glass-pill-ring-tint-tight,65%), white) calc(var(--hemma-glass-pill-glow-top-tight,0.30) * 100%), transparent) !important; --pill-glow-top-soft: color-mix(in srgb, color-mix(in srgb, var(--pill-accent,#ffffff) var(--hemma-glass-pill-ring-tint,40%), white) calc(var(--hemma-glass-pill-glow-top-soft,0.10) * 100%), transparent) !important; --pill-glow-bottom-tight: color-mix(in srgb, color-mix(in srgb, var(--pill-accent,#ffffff) var(--hemma-glass-pill-ring-tint-tight,65%), white) calc(var(--hemma-glass-pill-glow-bottom-tight,0.20) * 100%), transparent) !important; --pill-glow-bottom-soft: color-mix(in srgb, color-mix(in srgb, var(--pill-accent,#ffffff) var(--hemma-glass-pill-ring-tint,40%), white) calc(var(--hemma-glass-pill-glow-bottom-soft,0.06) * 100%), transparent) !important; }',
          'ha-card::after { content: ""; position: absolute; inset: -1px; border-radius: inherit; padding: 1px; background: conic-gradient(from 0deg, transparent 0deg 50deg, rgba(0,0,0,0.32) 80deg 100deg, transparent 130deg 230deg, rgba(0,0,0,0.32) 260deg 280deg, transparent 310deg 360deg); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; pointer-events: none; }',
          '@media (hover: hover) { :host(:hover) ha-card { box-shadow: inset 0 1px 0.5px -0.5px var(--pill-glow-top-tight), inset 0 -1px 0.5px -0.5px var(--pill-glow-bottom-tight), inset 0 3px 6px -3px var(--pill-glow-top-soft), inset 0 -3px 6px -3px var(--pill-glow-bottom-soft), inset 0 0 0 999px rgba(255,255,255,0.10) !important; } }',
          'ha-ripple { display: none !important; }',
        ].join('\n'),
      },
      styles: {
        card: [
          { background: 'var(--hemma-glass-pill-fill,rgba(255,255,255,0.12))' },
          { '--pill-accent': 'var(--hemma-popup-green-color,#30D158)' },
          { border: 'none' },
        ],
        name: [
          { 'font-size': '13px' }, { 'font-weight': '600' }, { 'letter-spacing': '0.01em' },
          { color: '#ffffff' },
          { 'white-space': 'nowrap' }, { 'font-family': 'var(--primary-font-family,system-ui)' },
        ],
      },
    };

    const emptyHeader = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: noHoverStyle },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '28px 28px 0 28px' }],
        grid: [{ 'grid-template-areas': '"title badge"' }, { 'grid-template-columns': '1fr auto' }, { 'align-items': 'flex-start' }],
        custom_fields: {
          title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
          badge: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
        },
      },
      custom_fields: {
        title: '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary);">'
          + '<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;">Media</div>'
          + '<div style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary);font-weight:400;">Plex \xb7 Recently Added</div>'
          + '</div>',
        badge: { card: emptyBadge },
      },
    };

    const emptyAdvice = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: noHoverStyle },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '20px 28px 18px 28px' }],
        grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { body: [{ 'justify-self': 'stretch' }, { width: '100%' }, { 'text-align': 'left' }] },
      },
      custom_fields: {
        body: '<div style="font-family:var(--primary-font-family,system-ui);">'
          + '<div style="font-size:22px;color:var(--primary-text-color,#ffffff);font-weight:400;letter-spacing:-.5px;">Nothing recently added</div>'
          + '</div>',
      },
    };

    return { type: 'vertical-stack', cards: [emptyHeader, emptyAdvice] };
  }

  /* responsive layout */
  const isMobile     = window.innerWidth < 600;
  const slideH       = isMobile ? 420 : 330;
  const swipeH       = slideH + 14;
  const summaryClamp = isMobile ? 8 : 7;

  /* shared extra_styles for transparent button-cards */
  const transparentStyles = 'ha-card{'
    + 'background:transparent!important;'
    + 'border:none!important;'
    + 'box-shadow:none!important;'
    + '-webkit-backdrop-filter:none!important;'
    + 'backdrop-filter:none!important;'
    + 'padding:0!important;'
    + 'border-radius:0!important;'
    + 'overflow:hidden!important;'
    + 'cursor:default!important;'
    + '}'
    + '#container{padding:0!important;height:100%!important;}'
    + 'ha-ripple{display:none!important;}';

  /* Media Type Pill */
  const typeBadge = (txt, accent) =>
    '<span style="position:relative;display:inline-flex;width:fit-content;'
    + 'font-size:10px;font-weight:700;letter-spacing:0.05em;color:#ffffff;'
    + 'background:' + accent + ';'
    + 'border-radius:999px;padding:6px 7px;'
    + 'white-space:nowrap;font-family:var(--primary-font-family,system-ui);">' + esc(txt) + '</span>';

  /* slide cards */
  const slideCards = items.map(function(item) {
    const posterUrl = resolveUrl(item.poster);
    const timeAgo   = ago(item.airdate);
    const isTV      = item._isTV;
    const badgeClr     = isTV ? '#A547FE' : '#FA7D24';
    const badgeTxt     = isTV ? 'TV SHOW' : 'MOVIE';
    const isWatched    = item.flag === false || item.flag === 'false';

    const posterImg = posterUrl
      ? '<img src="' + esc(posterUrl) + '" style="width:100%;height:100%;object-fit:cover;display:block;" loading="lazy"/>'
      : '<div style="width:100%;height:100%;background:rgba(255,255,255,0.04);display:flex;align-items:center;justify-content:center;"><ha-icon icon="mdi:plex" style="--mdc-icon-size:36px;color:rgba(255,255,255,0.2);"></ha-icon></div>';

    const dotSize  = isMobile ? 16 : 20;
    const dotIcon  = isMobile ?  8 : 11;
    const watchedDot = isWatched
      ? '<div style="position:absolute;top:6px;right:6px;width:' + dotSize + 'px;height:' + dotSize + 'px;background:rgba(255,255,255,0.3);border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 5px rgba(0,0,0,0.1);">'
        + '<svg viewBox="0 0 10 10" width="' + dotIcon + '" height="' + dotIcon + '"><polyline points="1.5,5 4,7.5 8.5,2.5" fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
        + '</div>'
      : '';

    const makePoster = (h, w, r) =>
      '<div style="position:relative;' + (w ? 'width:' + w + 'px;' : '') + 'height:' + h + 'px;border-radius:' + r + 'px;box-shadow:0 4px 16px rgba(0,0,0,0.4);">'
      + '<div style="position:relative;height:100%;border-radius:' + r + 'px;overflow:hidden;">'
        + posterImg
        + '<div style="position:absolute;inset:0;border-radius:' + r + 'px;pointer-events:none;'
          + 'box-shadow:var(--hemma-media-poster-highlight, inset 0 1px .5px -0.5px rgba(255,255,255,0.35), inset 0 -1px .5px -0.5px rgba(255,255,255,0.22));'
          + 'background:var(--hemma-media-poster-glow-top, linear-gradient(to bottom, rgba(255,255,255,0.30) 0%, rgba(255,255,255,0.12) 22%, rgba(255,255,255,0) 48%)), '
          + 'var(--hemma-media-poster-glow-bottom, linear-gradient(to top, rgba(255,255,255,0.30) 0%, rgba(255,255,255,0.12) 22%, rgba(255,255,255,0) 48%));"></div>'
      + '</div>'
      + watchedDot
      + '</div>';

    const episodeLine = isTV && (item.number || item.episode)
      ? '<div style="font-size:15px;line-height:1.5;font-weight:500;color:rgba(255,255,255,0.75);overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;">' + esc([item.number, item.episode].filter(Boolean).join(' \xb7 ')) + '</div>'
      : '';

    const yearGenreParts = [];
    if (!isTV && item.aired) {
      const yr = String(item.aired).slice(0, 4);
      if (/^\d{4}$/.test(yr)) yearGenreParts.push(yr);
    }
    if (item.genres) yearGenreParts.push(esc(item.genres));
    const yearGenreLine = yearGenreParts.length
      ? '<div style="font-size:15px;color:rgba(255,255,255,0.65);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + yearGenreParts.join(' \xb7 ') + '</div>'
      : '';

    const agoLine = timeAgo
      ? '<div style="font-size:15px;color:rgba(255,255,255,0.4);">Added ' + timeAgo + '</div>'
      : '';

    const summaryFont = 13;
    const sClamp = summaryClamp;
    const summaryLine = item.summary
      ? '<div style="font-size:' + summaryFont + 'px;color:rgba(255,255,255,0.5);padding-top:2px;line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:' + sClamp + ';-webkit-box-orient:vertical;word-break:break-word;text-align:left;">' + esc(item.summary) + '</div>'
      : '';

    const badgeSpan = typeBadge(badgeTxt, badgeClr);
    const titleDiv  = '<div style="font-size:20px;font-weight:700;color:var(--primary-text-color,#fff);line-height:1.25;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;">' + esc(item.title) + '</div>';
    const font      = 'font-family:var(--primary-font-family,\'Hanken Grotesk\',system-ui);';

    const slideHtml = isMobile
      /* mobile */
      ? '<div style="width:100%;height:' + slideH + 'px;padding:14px 20px 20px;overflow:hidden;box-sizing:border-box;' + font + 'display:flex;flex-direction:column;gap:14px;">'
        + '<div style="display:flex;flex-direction:row;gap:14px;align-items:flex-start;">'
        + makePoster(168, 112, 10)
        + '<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:8px;overflow:hidden;text-align:left;">'
        + badgeSpan + titleDiv + episodeLine + yearGenreLine + agoLine
        + '</div></div>'
        + summaryLine
        + '</div>'
      /* desktop: side-by-side grid */
      : '<div style="width:100%;display:grid;grid-template-columns:193px 1fr;height:' + slideH + 'px;padding:14px 28px 20px 22px;column-gap:18px;align-items:center;overflow:hidden;box-sizing:border-box;' + font + '">'
        + makePoster(290, null, 10)
        + '<div style="width:100%;min-width:0;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-start;text-align:left;gap:10px;white-space:normal;">'
        + badgeSpan + titleDiv + episodeLine + yearGenreLine + agoLine + summaryLine
        + '</div></div>';

    return {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false,
      show_name: false,
      show_label: false,
      show_state: false,
      extra_styles: transparentStyles,
      styles: {
        card: [
          { background: 'transparent' },
          { border: 'none' },
          { 'box-shadow': 'none' },
          { padding: '0' },
          { width: '100%' },
          { height: slideH + 'px' },
          { 'border-radius': '0' },
        ],
        grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { c: [{ 'justify-self': 'stretch' }, { height: '100%' }, { 'white-space': 'normal' }] },
      },
      custom_fields: { c: slideHtml },
    };
  });

  /* header */
  const headerCard = {
    type: 'custom:button-card',
    tap_action: { action: 'none' },
    show_icon: false,
    show_name: false,
    show_label: false,
    show_state: false,
    extra_styles: transparentStyles,
    styles: {
      card: [
        { background: 'transparent' },
        { border: 'none' },
        { 'box-shadow': 'none' },
        { padding: '0' },
        { 'border-radius': '0' },
      ],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'stretch' }] },
    },
    custom_fields: {
      c: '<div style="padding:20px ' + (isMobile ? '20px' : '28px') + ' 12px;">'
        + '<div style="text-align:left;">'
        + '<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;color:var(--primary-text-color,#fff);line-height:1.2;">Media</div>'
        + '<div style="font-size:14px;color:rgba(255,255,255,0.6);margin-top:2px;">Plex \xb7 Recently Added</div>'
        + '</div>'
        + '</div>',
    },
  };

  /* swipe-card (carousel, rounded bottom corners) */
  const bulletCss = items.map(function(item, idx) {
    const clr = item._isTV ? '#A547FE' : '#FA7D24';
    return '.swiper-pagination-bullet:nth-child(' + (idx+1) + ').swiper-pagination-bullet-active{width:30px!important;background:' + clr + '!important;}';
  }).join('');
  const swipeCard = {
    type: 'custom:swipe-card',
    card_mod: {
      style: 'ha-card,:host{'
        + 'background:transparent!important;'
        + 'box-shadow:none!important;'
        + 'border:none!important;'
        + 'border-radius:0 0 16px 16px!important;'
        + 'overflow:hidden!important;'
        + '}'
        + '.swiper,.swiper-container{height:' + swipeH + 'px!important;border-radius:0 0 16px 16px!important;overflow:hidden!important;}'
        + '.swiper-slide{width:100%!important;max-width:none!important;flex-shrink:0!important;}'
        + '.swiper-pagination-bullets{display:flex!important;flex-direction:row!important;gap:8px!important;align-items:center!important;justify-content:center!important;}'
        + '.swiper-pagination-bullet{width:15px!important;height:7px!important;border-radius:3px!important;background:rgba(255,255,255,0.15)!important;opacity:.9!important;margin:0!important;flex-shrink:0!important;transition:width 0.25s,background 0.25s!important;}'
        + bulletCss,
    },
    cards: slideCards,
    parameters: {
      autoplay: {
        delay: 6000,
        disableOnInteraction: false,
        pauseOnMouseEnter: false,
      },
      pagination: {
        clickable: true,
      },
      loop: false,
      speed: 450,
      slidesPerView: 1,
      spaceBetween: 0,
      observer: true,
      observeParents: true,
      resizeObserver: true,
    },
  };

  /* vertical-stack: pinned header above carousel */
  return {
    type: 'vertical-stack',
    card_mod: {
      style: ':host{--vertical-stack-card-gap:0px;}'
        + 'div{padding-bottom:0!important;}',
    },
    cards: [headerCard, swipeCard],
  };
]]]

