        + '<div style="font-size:16px;font-weight:500;letter-spacing:-0.01em;">System</div>'
        + '<div style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary, rgba(255,255,255,0.75));font-weight:400;">Updates · Software</div>'
      + '</div>',
      badge: { card: badgePillCard },
    },
  };

  /* Advice text */
  const adviceCard = {
    type: 'custom:button-card',
    entity: entity?.entity_id,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: noHoverStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '20px 28px 18px 28px' },
      ],
      grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { body: [{ 'justify-self': 'stretch' }, { width: '100%' }, { 'text-align': 'left' }] },
    },
    custom_fields: {
      body: `[[[
        ${_aggSnip}
        const advice = hasRestart && hasUpdates ? 'Restart + ' + count + ' update' + (count > 1 ? 's' : '')
                     : hasRestart ? 'Restart required'
                     : hasUpdates ? 'Available Updates'
                     : 'Everything is up to date';
        return '<div style="font-family:var(--primary-font-family,system-ui);">'
          + '<div style="font-size:22px;color:var(--primary-text-color,#ffffff);font-weight:400;letter-spacing:-.5px;">' + advice + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Tile factory */
  const makeTileCard = (entityId) => {
    const _eid = JSON.stringify(entityId);

    const _kindSnip = `
      const eid = ${_eid};
      const e = states[eid];
      const rs = (e?.attributes?.release_summary || '').toLowerCase();
      const needsRestart = rs.includes('restart') && e?.state === 'off' && e?.attributes?.installed_version === e?.attributes?.latest_version;
      const hasUpdate = e?.state === 'on';
      const inProg = e?.attributes?.in_progress === true;
    `;

    const pillCard = {
      type: 'custom:button-card',
      entity: entityId,
      tap_action: `[[[
        ${_kindSnip}
        if (needsRestart) return { action: 'call-service', service: 'homeassistant.restart', service_data: {}, confirmation: { text: 'Restart Home Assistant now?' } };
        if (hasUpdate && inProg) return { action: 'none' };
        return { action: 'more-info' };
      ]]]`,
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: {
        style: [
          ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; opacity: 0; animation: hemmaPillReveal 0s linear 0.2s forwards; }',
          '@keyframes hemmaPillReveal { to { opacity: 1; } }',
          'ha-card { border: none !important; border-radius: 999px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: pointer !important; transition: background 0.2s ease, opacity 0.2s ease, filter 0.15s ease, transform 0.15s ease !important; }',
          'ha-card:hover { filter: brightness(1.18) !important; transform: scale(1.008) !important; }',
          'ha-ripple { display: none !important; }',
        ].join('\n'),
      },
      styles: {
        card: [
          { background: `[[[
            ${_kindSnip}
            if (needsRestart) return 'rgba(255,214,0,0.2)';
            if (hasUpdate) return inProg ? 'rgba(68,152,195,0.35)' : 'var(--hemma-popup-primary-color, #00c3d0)';
            return 'rgba(103,245,160,0.18)';
          ]]]` },
          { 'border-radius': '999px' }, { 'box-shadow': 'none' },
          { padding: `[[[ return window.matchMedia('(max-width:600px)').matches ? '9px 14px' : '12px 20px'; ]]]` },
        ],
        grid: [{ 'grid-template-areas': '"label"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { label: [{ 'justify-self': 'center' }] },
      },
      custom_fields: {
        label: `[[[
          ${_kindSnip}
          const isMobile = window.matchMedia('(max-width:600px)').matches;
          const fontSize = isMobile ? '13px' : '14px';
          let text, color;
          if (needsRestart) { text = 'Restart'; color = 'var(--hemma-popup-yellow-color, #ffd600)'; }
          else if (hasUpdate) {
            text = inProg ? 'Updating...' : 'Details';
            color = inProg ? 'rgba(255,255,255,0.55)' : '#ffffff';
          } else {
            text = 'Details';
            color = 'var(--hemma-popup-green-color, #30D158)';
          }
          return '<span style="font-size:' + fontSize + ';font-weight:600;color:' + color + ';white-space:nowrap;letter-spacing:0.01em;">' + text + '</span>';
        ]]]`,
      },
    };

    return {
      type: 'custom:button-card',
      entity: entityId,
      tap_action: `[[[
        ${_kindSnip}
        if (hasUpdate && inProg) return { action: 'none' };
        return { action: 'more-info' };
      ]]]`,
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: tileTapStyle },
      styles: {
        card: [
          { background: 'var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08))' }, { border: 'none' }, { 'border-radius': '24px' },
          { 'box-shadow': 'none' },
          { padding: `[[[ return window.matchMedia('(max-width:600px)').matches ? '14px 12px 14px 14px' : '16px 16px 16px 20px'; ]]]` },
        ],
        grid: [
          { 'grid-template-areas': '"body update"' },
          { 'grid-template-columns': '1fr auto' },
          { 'align-items': 'center' },
        ],
        custom_fields: {
          body:   [{ 'justify-self': 'stretch' }, { 'text-align': 'left' }, { 'min-width': '0' }, { overflow: 'hidden' }],
          update: [{ 'justify-self': 'end' }, { 'align-self': 'center' }],
        },
      },
      custom_fields: {
        body: `[[[
          ${_kindSnip}
          const name = (e?.attributes?.friendly_name || eid).replace(/ Update$/i, '').replace(/ Firmware$/i, '');
          let picture = e?.attributes?.entity_picture;
          if (picture && picture.startsWith('/api/brands/')) {
            const p = picture.split('/');
            picture = 'https://brands.home-assistant.io/_/' + p[p.length - 2] + '/' + p[p.length - 1];
          }
          const isMobile = window.matchMedia('(max-width:600px)').matches;
          const iconPx   = isMobile ? 24 : 28;
          const gapPx    = isMobile ? 8  : 12;
          const nameFont = isMobile ? 13 : 14;
          const subFont  = isMobile ? 11 : 12;
          const iconHtml = picture
            ? '<img src="' + picture + '" style="width:' + iconPx + 'px;height:' + iconPx + 'px;border-radius:8px;object-fit:contain;flex-shrink:0;" />'
            : '<div style="width:' + iconPx + 'px;height:' + iconPx + 'px;border-radius:8px;background:rgba(255,255,255,0.08);flex-shrink:0;display:flex;align-items:center;justify-content:center;">'
              + '<ha-icon icon="mdi:package-variant" style="--mdc-icon-size:16px;width:16px;height:16px;color:rgba(255,255,255,0.35);"></ha-icon></div>';

          let textHtml;
          if (needsRestart) {
            const version = e?.attributes?.installed_version || '—';
            textHtml = '<div style="font-size:' + nameFont + 'px;color:var(--hemma-popup-tiles-text-primary,#ffffff);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + name + '</div>'
              + '<div style="font-size:' + subFont + 'px;color:var(--hemma-popup-yellow-color,#ffd600);margin-top:3px;">' + version + ' · Restart pending</div>';
          } else if (hasUpdate) {
            const installed = e?.attributes?.installed_version || '—';
            const latest = e?.attributes?.latest_version || '—';
            const nameColor = inProg ? 'rgba(255,255,255,0.4)' : 'var(--hemma-popup-tiles-text-primary, #ffffff)';
            const latestColor = inProg ? 'rgba(68,152,195,0.4)' : 'var(--hemma-popup-primary-color, #00c3d0)';
            textHtml = '<div style="font-size:' + nameFont + 'px;color:' + nameColor + ';font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + name + '</div>'
              + '<div style="font-size:' + subFont + 'px;color:var(--hemma-popup-tiles-text-muted, rgba(255,255,255,0.52));margin-top:3px;">'
                + installed + ' → <span style="color:' + latestColor + ';">' + latest + '</span>'
              + '</div>';
          } else {
            const version = e?.attributes?.installed_version || '—';
            textHtml = '<div style="font-size:' + nameFont + 'px;color:var(--hemma-popup-tiles-text-primary,#ffffff);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + name + '</div>'
              + '<div style="font-size:' + subFont + 'px;color:var(--hemma-popup-green-color,#30D158);margin-top:3px;">' + version + ' · Up to date</div>';
          }

          return '<div style="display:flex;align-items:center;gap:' + gapPx + 'px;min-width:0;">'
            + iconHtml
            + '<div style="min-width:0;overflow:hidden;">' + textHtml + '</div>'
            + '</div>';
        ]]]`,
        update: { card: pillCard },
      },
    };
  };

  const allTileAreas = [
    ...restartEntities.map((_, i) => '"r' + i + '"'),
    ...updates.map((_, i) => '"u' + i + '"'),
  ].join(' ');
  const tileCustomFields = {};
  const tileFieldStyles  = {};
  restartEntities.forEach((e, i) => {
    tileCustomFields['r' + i] = { card: makeTileCard(e.entity_id) };
    tileFieldStyles['r'  + i] = [{ 'justify-self': 'stretch' }];
  });
  updates.forEach((e, i) => {
    tileCustomFields['u' + i] = { card: makeTileCard(e.entity_id) };
    tileFieldStyles['u'  + i] = [{ 'justify-self': 'stretch' }];
  });

  const listCard = hasAny ? {
    type: 'custom:button-card',
    entity: entity?.entity_id,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: noHoverStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '4px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': allTileAreas },
        { 'grid-template-columns': '1fr' },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFieldStyles,
    },
    custom_fields: tileCustomFields,
  } : null;

  const cards = hasAny ? [headerCard, adviceCard, listCard] : [headerCard, adviceCard];

  return { type: 'vertical-stack', cards };
]]]

hemma_mobile_bg.extra_styles:
/* LAYER 2 — the photo, uniformly blurred */
:host ha-card::after {
  content: "" !important;
  inset:
    calc(-1 * var(--hemma-hero-overscan))
    calc(-1 * var(--hemma-hero-overscan))
    var(--hemma-hero-overscan) !important;
  z-index: -10 !important;
  pointer-events: none !important;
  background-color: transparent !important;
  background-image: var(--hemma-mobile-hero-img) !important;
  background-size:
    auto calc(var(--hemma-mobile-hero-height, 28%) + var(--hemma-safe-top)
              + var(--hemma-hero-overscan)) !important;
  background-position:
    var(--hemma-mobile-hero-x, 50%) var(--hemma-mobile-hero-y, 0%) !important;
  background-repeat: no-repeat !important;
  filter:
    blur(var(--hemma-mobile-hero-blur, 2px))
    contrast(var(--hemma-mobile-hero-photo-contrast, 0.90))
    saturate(var(--hemma-mobile-hero-photo-saturate, 0.94))
    brightness(var(--hemma-mobile-hero-photo-brightness, 1.05)) !important;
  transform: none !important;
  animation: none !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
}

/* LANDSCAPE */
@media (orientation: landscape) and (max-height: 500px) {
  :host ha-card::after {
    background-size: 100% auto !important;
  }
  :host ha-card {
    --hemma-mobile-hero-fade-start:
      var(--hemma-mobile-hero-fade-start-landscape, 76%);
    --hemma-mobile-hero-p-handoff:
      var(--hemma-mobile-hero-p-handoff-landscape, 96%);
    --hemma-mobile-hero-p-upper:
      var(--hemma-mobile-hero-p-upper-landscape, 97%);
    --hemma-mobile-hero-p-mid:
      var(--hemma-mobile-hero-p-mid-landscape, 98%);
    --hemma-mobile-hero-p-lower:
      var(--hemma-mobile-hero-p-lower-landscape, 99%);
    --hemma-mobile-hero-wash-mid:
      var(--hemma-mobile-hero-wash-mid-landscape, 30%);
    --hemma-mobile-hero-wash-end:
      var(--hemma-mobile-hero-wash-end-landscape, 58%);
    --hemma-mobile-hero-mesh-a:
      var(--hemma-mobile-hero-mesh-a-landscape, transparent);
    --hemma-mobile-hero-mesh-b:
      var(--hemma-mobile-hero-mesh-b-landscape, transparent);
  }
}

/* LAYER 3 — wash, mesh and the color gradient */
:host ha-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -9;
  pointer-events: none;
  background-image:
    /* Wash */
    linear-gradient(
      to bottom,
      var(--hemma-mobile-hero-tint-top, rgba(28,24,20,0.34)) 0%,
      var(--hemma-mobile-hero-tint-bot, rgba(28,24,20,0.12))
        calc(var(--hemma-mobile-hero-wash-mid, 27%) + var(--hemma-safe-top)),
      transparent
        calc(var(--hemma-mobile-hero-wash-end, 70%) + var(--hemma-safe-top))),
    /* Mesh — derived from the photo by hemma-core.js */
    radial-gradient(
      var(--hemma-mobile-hero-mesh-a-size, 120% 46%) at
        var(--hemma-mobile-hero-mesh-a-pos, 18% 58%),
      var(--hemma-mobile-hero-mesh-a, transparent) 0%,
      transparent 72%),
    radial-gradient(
      var(--hemma-mobile-hero-mesh-b-size, 130% 50%) at
        var(--hemma-mobile-hero-mesh-b-pos, 88% 92%),
      var(--hemma-mobile-hero-mesh-b, transparent) 0%,
      transparent 70%),
    /* The dissolve the photo hands over to. */
    linear-gradient(
      var(--hemma-mobile-hero-angle, 180deg),
      transparent
        calc(var(--hemma-mobile-hero-fade-start, 12%) + var(--hemma-safe-top)),
      var(--hemma-mobile-hero-c-handoff, #90857b)
        calc(var(--hemma-mobile-hero-p-handoff, 30%) + var(--hemma-safe-top)),
      var(--hemma-mobile-hero-c-upper, #807870)
        calc(var(--hemma-mobile-hero-p-upper, 55%) + var(--hemma-safe-top)),
      var(--hemma-mobile-hero-c-mid, #706a64)
        calc(var(--hemma-mobile-hero-p-mid, 67%) + var(--hemma-safe-top)),
      var(--hemma-mobile-hero-c-lower, #615d59)
        calc(var(--hemma-mobile-hero-p-lower, 80%) + var(--hemma-safe-top)),
      var(--hemma-mobile-hero-c-base, #524f4d)
        calc(var(--hemma-mobile-hero-p-base, 100%) + var(--hemma-safe-top)));
  background-size:
    100% 100%,
    100% 100%,
    100% 100%,
    100% 100%;
  background-position:
    0 0,
    0 0,
    0 0,
    0 0;
  background-repeat: no-repeat;
}

