[[[
  let eid = variables?.light_group_entity || variables?.entity_1 || entity?.entity_id;
  if (!eid) return 'hemma_light_group_popup';
  const mems0 = states[eid]?.attributes?.entity_id;
  const isFlat = !Array.isArray(mems0) || !Array.isArray(states[mems0[0]]?.attributes?.entity_id);
  if (isFlat) {
    for (const sid of Object.keys(states)) {
      if (!sid.startsWith('light.') || sid === eid) continue;
      // Keys-then-lookup: Object.keys hits the Proxy's ownKeys trap (no
      // registration); reading states[sid] here subscribes to lights only,
      // not to all ~1500 entities the way Object.entries(states) did.
      const st = states[sid];
      const mems = st.attributes?.entity_id;
      if (Array.isArray(mems) && mems.includes(eid) && mems.length > 1
          && Array.isArray(states[mems[0]]?.attributes?.entity_id)) {
        eid = sid; break;
      }
    }
  }
  return eid.replace(/\./g, '_') + '_popup';
]]]

