hemma_badge_presence_group.name:
[[[
  const entities = [
    variables?.entity_1, variables?.entity_2,
    variables?.entity_3, variables?.entity_4
  ].filter(Boolean);

  if (!entities.length) return '';

  const getState = (eid) =>
    String(hass.states[eid]?.state || '').toLowerCase().replace(/_/g, ' ');
  const getName = (eid) =>
    String(hass.states[eid]?.attributes?.friendly_name || '').split(' ')[0] || 'Person';
  const isHome = (eid) => { const s = getState(eid); return s === 'home' || s === 'just arrived'; };

  const homeCount   = entities.filter(isHome).length;
  const awayEntities = entities.filter(e => !isHome(e));

  let title, status;
  if (entities.length === 1) {
    title  = getName(entities[0]);
    status = isHome(entities[0]) ? 'Home' : 'Away';
  } else {
    title = 'People';
    if (homeCount === entities.length)  status = 'All Home';
    else if (homeCount === 0)           status = 'All Away';
    else                                status = `${awayEntities.length} Away`;
  }

  const esc = (t) => String(t || '').replaceAll('"', '&quot;');
  return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      <div class="badge-sub">${esc(status)}</div>
    </div>
  `;
]]]

hemma_badge_security.icon:
[[[
  const id = String(entity?.entity_id || '');
  const dom = id.split('.')[0];
  const s = String(entity?.state || '').toLowerCase();
  const dc = String(entity?.attributes?.device_class || '').toLowerCase();

  if (dom === 'lock') return s === 'locked' ? 'mdi:lock' : 'mdi:lock-open-variant';
  if (dom === 'alarm_control_panel')
    return s === 'disarmed' ? 'mdi:shield-off-outline' : 'mdi:shield-check';
  if (dom === 'camera') return 'mdi:cctv';
  if (dc === 'garage' || dc === 'garage_door') return 'mdi:garage';
  if (dc === 'window') return s === 'on' ? 'mdi:window-open' : 'mdi:window-closed';
  if (dc === 'motion') return 'mdi:motion-sensor';
  return s === 'on' ? 'mdi:door-open' : 'mdi:door-closed';
