ha-card{
  background: none !important;
  box-shadow: none !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

ha-card{
  will-change: auto !important;
  contain: none !important;
}

hemma_now_playing.extra_styles:
/* Tablet - Now Playing Padding */
@media (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (hover: none) {
  #np_head {
    padding-bottom: 26px !important;
  }
}

:host{
  --np-hold: calc((1 - var(--np-open, 0)) * 0.42s);
  --np-shadow:
    calc(var(--np-open, 0) * var(--np-shell, 1) * 1px)
    calc(var(--np-open, 0) * var(--np-shell, 1) * 2px)
    calc(var(--np-open, 0) * var(--np-shell, 1) * 4px) rgba(0,0,0,0.06),
    0 calc(var(--np-open, 0) * var(--np-shell, 1) * 14px)
      calc(var(--np-open, 0) * var(--np-shell, 1) * 40px) rgba(0,0,0,0.10);
  display: block;
  width: 100%;
  max-height: calc(var(--np-open, 0) * var(--np-vp, 1) * 640px);
  opacity: var(--np-vp, 1);
  visibility: var(--np-vis, visible);
  transition:
    opacity .30s ease,
    max-height 0s var(--np-hold, 0s),
    visibility 0s var(--np-hold, 0s);
