np_art_init.value:
[[[
  if (typeof window._hemmaNPArt !== 'function') {
    window._hemmaNPArt = function (src) {
      const hold = window._hemmaNPArtHold = window._hemmaNPArtHold || {};
      const warm = window._hemmaNPArtWarm = window._hemmaNPArtWarm || new Map();
      const path = (u) => String(u || '').split('?')[0];
      const k = src?.key || '';
      const cur = src?.art || null;
      const id = src ? ((src.title || '') + '|' + (src.subtitle || '')) : '';

      let u = cur;
      if (k) {
        const prev = hold[k];
        const sameTrack = !!(prev && prev.id === id);
        if (cur && sameTrack && path(prev.url) === path(cur) && warm.has(path(cur))) u = prev.url;
        else if (cur) hold[k] = { id: id, url: cur };
        // Transient null between polls — hold the last good art, but only for this track.
        else u = sameTrack ? prev.url : null;
      }

      // Retaining a decoded Image keeps the bitmap alive across a rebuild
      // (feedback_preload_needs_decode_not_hidden_img).
      if (u && !warm.has(path(u))) {
        try {
          const im = new Image();
          im.decoding = 'async';
          im.src = u;
          warm.set(path(u), im);
          if (warm.size > 24) warm.delete(warm.keys().next().value);
          im.decode?.().catch(() => {});
        } catch (e) {}
      }

      return u || null;
    };
  }
  return true;
]]]

data.content:
[[[
  const sid = variables?.hold_src?.entity || '';
  return window._hemmaPlexPopupCard(sid, states);
]]]

card.--np-chip:
[[[
  // Keyed by slot_id, not `this` — this element gets torn down/rebuilt on ordinary content updates.
  window._hemmaNPSlotState = window._hemmaNPSlotState || {};
  const store = variables.slot_id
    ? (window._hemmaNPSlotState[variables.slot_id] = window._hemmaNPSlotState[variables.slot_id] || {})
    : this;
  const el = this;

  const hasSrc = !!variables.hold_src;
  const panelOpen = states[variables.minimized_entity]?.state !== 'on';
  const open = hasSrc ? 1 : 0;
  try {
    el.style.setProperty('--np-chip', String(open));
    // Must gate on both hasSrc AND panelOpen — this lives on ha-card itself and overrides the np_rail wrapper's ancestor pointer-events rule.
    el.style.setProperty('--np-chip-ptr', (hasSrc && panelOpen) ? 'auto' : 'none');
    // Open snaps instant so the FLIP below measures the final size; close eases.
    el.style.setProperty('--np-chip-geo', open ? '0s' : '.34s');
  } catch (e) {}

  // Chip already open and shifted because something was inserted above — start at last position and let it travel.
  const prevOpen = store._npChipOpen ?? 0;
  const prevTop = store._npChipTop;
  if (open && prevOpen === 1 && prevTop !== undefined) {
    requestAnimationFrame(() => {
      const card = el.shadowRoot?.querySelector('ha-card');
      if (!card) return;
      // offsetTop, not getBoundingClientRect(): a transformed ancestor (the panel's droplet animation) skews rect-based deltas; layout offsets ignore transforms.
      const nowTop = card.offsetTop + (card.offsetParent?.offsetTop || 0);
      const delta = prevTop - nowTop;
      store._npChipTop = nowTop;
      if (Math.abs(delta) < 1) return;
      try { store._npShiftAnim?.cancel(); } catch (e) {}

      // Last chip gets extra squash on landing — end of the queue absorbing the shove.
      const list = window._hemmaNPCache?.list || [];
      const isLast = Number(variables.slot || 1) === (list.length - 1);
      const frames = isLast
        ? [
            { transform: `translateY(${delta.toFixed(1)}px) scale(1, 1)` },
            { transform: 'translateY(2.5px) scale(1, 0.93)', offset: 0.8 },
            { transform: 'translateY(0) scale(1, 1)' },
          ]
        : [
            { transform: `translateY(${delta.toFixed(1)}px)` },
            { transform: 'translateY(0)' },
          ];

      store._npShiftAnim = card.animate(frames, {
        duration: isLast ? 620 : 560,
        easing: 'cubic-bezier(0.25, 0.9, 0.3, 1)',
        fill: 'both',
      });
      // fill:'both' leaves the animation live forever unless canceled — a permanently-active transform on ha-card can mis-clip its rounded overflow:hidden descendants.
      store._npShiftAnim.finished
        .then(() => { try { store._npShiftAnim?.cancel(); } catch (e) {} })
        .catch(() => {});
    });
  } else if (open) {
    requestAnimationFrame(() => {
      const card = el.shadowRoot?.querySelector('ha-card');
      if (card) store._npChipTop = card.offsetTop + (card.offsetParent?.offsetTop || 0);
    });
  }

  const prev = store._npChipOpen ?? 0;
  if (prev !== open) {
    requestAnimationFrame(() => {
      const card = el.shadowRoot?.querySelector('ha-card');
      if (!card) return;
      try { store._npChipAnim?.cancel(); } catch (e) {}

      let frames;
      let dur = open ? 560 : 320;

      const dem = window._hemmaNPDemoted;
      const pr  = window._hemmaNPPrimaryRect;
      const isDemoted = open && dem && pr &&
        dem.key === variables.hold_src?.key &&
        (Date.now() - dem.at) < 1500;

      if (isDemoted) {
        const cr = card.getBoundingClientRect();
        if (cr.width > 4 && cr.height > 4) {
          // Capped at 1.75 — the true ~2.3x scale read as a pill inflated past anything on screen.
          const sx = pr.width / cr.width;
          const sy = Math.min(pr.height / cr.height, 1.75);
          const dx = (pr.left + pr.width  / 2) - (cr.left + cr.width  / 2);
          const dy = (pr.top  + pr.height / 2) - (cr.top  + cr.height / 2);
          const R = 20;
          const restRadius = getComputedStyle(card).getPropertyValue('--np-chip-radius').trim() || '16px';
          frames = [
            { transform: `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`,
              borderRadius: `${(R / sx).toFixed(1)}px / ${(R / sy).toFixed(1)}px`,
              opacity: 1 },
            { transform: `translate(0px, 3px) scale(1, 0.94)`,
              borderRadius: restRadius, opacity: 1, offset: 0.82 },
            { transform: 'translate(0px, 0px) scale(1, 1)',
              borderRadius: restRadius, opacity: 1 },
          ];
          dur = 600;
        }
      }

      if (!frames) {
        // Opacity only, not transform — an active transform animation on this element would suppress its own backdrop-filter for the duration, and this chip must stay blurred continuously.
        frames = open
          ? [{ opacity: 0 }, { opacity: 1 }]
          : [{ opacity: 1 }, { opacity: 0 }];
      }

      store._npChipAnim = card.animate(frames, {
        duration: dur,
        easing: 'cubic-bezier(0.25, 0.9, 0.3, 1)',
        fill: 'both',
      });
      store._npChipAnim.finished
        .then(() => {
          store._npChipTop = card.offsetTop + (card.offsetParent?.offsetTop || 0);
          try { store._npChipAnim?.cancel(); } catch (e) {}
        })
        .catch(() => {});
    });
  }
  // Published rect is where the primary tile expands from on promote (mirror of the demotion FLIP).
  if (open && variables.hold_src?.key) {
    requestAnimationFrame(() => {
      const card = el.shadowRoot?.querySelector('ha-card');
      if (!card) return;
      const r = card.getBoundingClientRect();
      if (r.width > 4 && r.height > 4) {
        window._hemmaNPChipRects = window._hemmaNPChipRects || {};
        window._hemmaNPChipRects[variables.hold_src.key] = r;
      }
    });
  }

  store._npChipOpen = open;
  return open;
]]]

