routes.popup:
[[[
  const reg = hass.entities;

  const getRegEntry = (id) => {
    if (!reg) return null;
    if (Array.isArray(reg)) return reg.find(e => e?.entity_id === id) || null;
    return reg[id] || (reg.get ? reg.get(id) : null) || null;
  };

  // Keys-then-lookup: ownKeys doesn't register entities, get does.
  const scenes = Object.keys(hass.states || {})
    .filter(id => id.startsWith('scene.'))
    .map(id => hass.states[id])
    .filter(s => !s.entity_id.startsWith('scene.hemma_restore_'))
    // Exclude dynamically-created scenes (not in the entity registry)
    .filter(s => !!getRegEntry(s.entity_id))
    // Exclude scenes hidden/disabled in HA
    .filter(s => {
      const e = getRegEntry(s.entity_id);
      return !(e.hidden || e.hidden_by || e.disabled || e.disabled_by);
    })
    .slice()
    .sort((a,b) => (a.attributes?.friendly_name || a.entity_id)
      .localeCompare(b.attributes?.friendly_name || b.entity_id));

  return scenes.map(s => ({
    label: s.attributes?.friendly_name || s.entity_id.replace('scene.',''),
    icon: s.attributes?.icon || 'mdi:layers',
    tap_action: {
      action: 'call-service',
      service: 'scene.turn_on',
      service_data: { entity_id: s.entity_id, transition: 3 }
    }
  }));
]]]

